drop function if exists public.vote_poll(uuid, integer);

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- 20261031000000_relax_signup_limit.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- Relax account-creation limits: 25 accounts per network (was 6) and raise
-- the Supabase auth sign-in/sign-up rate limit in config.toml accordingly.
create or replace function public.before_user_created(event jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_ip   text := nullif(event -> 'metadata' ->> 'ip_address', '');
  v_hash text;
  v_used integer;
begin
  if v_ip is null then return '{}'::jsonb; end if;
  v_hash := encode(extensions.digest(
    (select value from public.platform_config where key = 'ip_pepper') || '|' || v_ip, 'sha256'), 'hex');
  select count(*) into v_used from public.signup_ips s
  where s.ip_hash = v_hash and (s.user_id is null or exists (select 1 from auth.users u where u.id = s.user_id));
  if v_used >= 25 then
    return jsonb_build_object('error', jsonb_build_object(
      'http_code', 429, 'message', 'Too many accounts have been created from this network. Try again later.'));
  end if;
  insert into public.signup_ips (ip_hash, user_id)
  values (v_hash, nullif(event -> 'user' ->> 'id', '')::uuid);
  return '{}'::jsonb;
end;
$$;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- 20261101000000_disposable_accounts.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- Disposable accounts: anonymous sign-ins that expire after 7 days unless an
-- email is added. All data is removed on expiry.
alter table public.profiles
  add column if not exists disposable boolean not null default false,
  add column if not exists expires_at timestamptz;

create index if not exists profiles_disposable_expires_idx
  on public.profiles (expires_at) where disposable = true;

-- Bootstrap: read the disposable flag from signup metadata.
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  v_username text := lower(coalesce(new.raw_user_meta_data ->> 'username', ''));
  v_display  text := coalesce(nullif(btrim(new.raw_user_meta_data ->> 'display_name'), ''), v_username);
  v_disposable boolean := coalesce((new.raw_user_meta_data ->> 'disposable')::boolean, false);
begin
  if v_username !~ '^[a-z0-9_.]{2,32}$' then
    raise exception 'invalid username';
  end if;
  insert into public.profiles (id, username, display_name, avatar_color, disposable, expires_at)
  values (new.id, v_username, left(v_display, 32),
          (array['#7c5cff','#e5484d','#30a46c','#f76b15','#0090ff','#d6409f','#ffb224','#12a594'])
            [1 + floor(random() * 8)::int],
          v_disposable,
          case when v_disposable then now() + interval '7 days' else null end);
  return new;
end;
$$;

-- Disposable accounts cannot change their username.
create or replace function public.set_username(p_username text)
returns void language plpgsql security definer set search_path = '' as $$
declare
  v text := lower(btrim(coalesce(p_username, '')));
  v_disposable boolean;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select disposable into v_disposable from public.profiles where id = auth.uid();
  if v_disposable then raise exception 'disposable accounts cannot change their username'; end if;
  if not public.username_available(v) then
    raise exception 'that username is taken or invalid';
  end if;
  update public.profiles set username = v where id = auth.uid();
  if not found then raise exception 'profile not found'; end if;
end;
$$;

-- Promote a disposable account to permanent once an email is verified.
create or replace function public.make_account_permanent()
returns void language plpgsql security definer set search_path = '' as $$
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  update public.profiles
     set disposable = false, expires_at = null
   where id = auth.uid();
end;
$$;

-- Remove expired disposable accounts' data.
create or replace function public.purge_expired_disposable()
returns integer language plpgsql security definer set search_path = '' as $$
declare
  v_count integer := 0;
  r record;
begin
  for r in select id from public.profiles where disposable = true and expires_at is not null and expires_at < now() loop
    delete from public.profiles where id = r.id;
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;

revoke execute on function public.make_account_permanent() from public, anon;
grant execute on function public.make_account_permanent() to authenticated;
revoke execute on function public.purge_expired_disposable() from public, anon, authenticated;
grant execute on function public.purge_expired_disposable() to service_role;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- 20261103000000_fix_username_taken.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- Fix "username already taken" signup failures.
--
-- 20261101000000_disposable_accounts.sql replaced handle_new_user() and lost
-- the self-healing behaviour from 20260930000000_profile_self_heal.sql: an
-- invalid username raised, and a taken one crashed the insert with a unique
-- violation ("Database error saving new user"). This restores the fallback to
-- a safe unique username while keeping the disposable-account fields.
--
-- Safe to run more than once.

create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  v_wanted     text := lower(btrim(coalesce(new.raw_user_meta_data ->> 'username', '')));
  v_username   text;
  v_display    text;
  v_disposable boolean := coalesce((new.raw_user_meta_data ->> 'disposable')::boolean, false);
  v_try        integer := 0;
begin
  loop
    if v_try = 0 and v_wanted ~ '^[a-z0-9_.]{2,32}$'
       and not exists (select 1 from public.profiles where username = v_wanted) then
      v_username := v_wanted;
    else
      v_username := public.unique_username(coalesce(nullif(v_wanted, ''), split_part(coalesce(new.email, ''), '@', 1)));
    end if;
    v_display := coalesce(nullif(btrim(new.raw_user_meta_data ->> 'display_name'), ''), v_username);
    begin
      insert into public.profiles (id, username, display_name, avatar_color, disposable, expires_at)
      values (new.id, v_username, left(v_display, 32),
              (array['#7c5cff','#e5484d','#30a46c','#f76b15','#0090ff','#d6409f','#ffb224','#12a594'])
                [1 + floor(random() * 8)::int],
              v_disposable,
              case when v_disposable then now() + interval '7 days' else null end)
      on conflict (id) do nothing;
      return new;
    exception when unique_violation then
      -- someone grabbed the same name a moment ago: pick another and retry
      v_try := v_try + 1;
      if v_try > 5 then raise; end if;
    end;
  end loop;
end;
$$;

grant execute on function public.handle_new_user() to supabase_auth_admin;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- 20261104000000_restore_resolve_login.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- Restore resolve_login() (20261104000000)
--
-- Fixes: "Could not find the function public.resolve_login(p_identifier) in
-- the schema cache". Self-contained and safe to run more than once, so it also
-- works on a database where earlier migrations were skipped or half-applied.
--
-- Also fixes two bugs in the previous version:
--   * usernames typed with capitals ("Alice") never resolved
--   * an account unbanned in Supabase Auth (banned_until in the past) was
--     still reported as banned
-- =============================================================================

-- column the ban check reads (added by 20261002000000_platform.sql)
alter table public.profiles
  add column if not exists account_status text not null default 'active';

-- per-IP throttle log; RLS on with no policies = only this function touches it
create table if not exists public.login_lookups (
  id              bigserial primary key,
  ip              text not null default '',
  identifier_hash text not null default '',
  attempted_at    timestamptz not null default now()
);
create index if not exists login_lookups_ip_time_idx on public.login_lookups (ip, attempted_at desc);
create index if not exists login_lookups_time_idx on public.login_lookups (attempted_at);
alter table public.login_lookups enable row level security;

drop function if exists public.resolve_login(text);
create function public.resolve_login(p_identifier text)
returns table (email text, username text, banned boolean)
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_headers    text;
  v_ip         text := '';
  v_attempts   integer;
  v_identifier text := lower(btrim(coalesce(p_identifier, '')));
begin
  if v_identifier = '' then return; end if;

  -- best-effort client IP, used only to throttle lookups
  begin
    v_headers := current_setting('request.headers', true);
    if v_headers is not null and v_headers <> '' then
      v_ip := btrim(coalesce(
        nullif(split_part(coalesce(v_headers::json ->> 'x-forwarded-for', ''), ',', 1), ''),
        nullif(v_headers::json ->> 'cf-connecting-ip', ''),
        ''
      ));
    end if;
  exception when others then
    v_ip := '';
  end;

  if v_ip <> '' then
    delete from public.login_lookups where attempted_at < now() - interval '1 day';
    select count(*) into v_attempts
      from public.login_lookups
     where ip = v_ip and attempted_at > now() - interval '10 minutes';
    if v_attempts >= 20 then
      raise exception 'Too many login attempts. Please wait a few minutes and try again.';
    end if;
    insert into public.login_lookups (ip, identifier_hash) values (v_ip, md5(v_identifier));
  end if;

  return query
    select u.email::text,
           p.username::text,
           ((u.banned_until is not null and u.banned_until > now()) or p.account_status = 'banned') as banned
      from auth.users u
      join public.profiles p on p.id = u.id
     where (position('@' in v_identifier) = 0 and v_identifier ~ '^[a-z0-9_.]{2,32}$' and p.username = v_identifier)
        or (position('@' in v_identifier) > 0 and lower(u.email) = v_identifier)
     limit 1;
end;
$$;

revoke execute on function public.resolve_login(text) from public;
grant execute on function public.resolve_login(text) to anon, authenticated;

-- make the API see the new function immediately (fixes the "schema cache" error)
notify pgrst, 'reload schema';

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- 20261104010000_vdl_account_export.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- VDL account export (20261104010000)
--
-- Lets the VDL backend pull every account (auth user + profile) so accounts
-- keep the SAME user id, email, username and password in VDL.
--
-- * service_role ONLY: never callable from the browser (anon/authenticated).
-- * keyset-paginated by id so it works for any number of accounts.
-- * profile comes back as jsonb, so it works even if some profile columns
--   were never migrated on this database.
-- * encrypted_password is the bcrypt hash Supabase Auth already stores; the
--   plaintext password is never available (and Venband only ever sends a
--   key derived on the user's device anyway).
--
-- Safe to run more than once.
-- =============================================================================

drop function if exists public.vdl_export_accounts(uuid, integer);
create function public.vdl_export_accounts(p_after uuid default null, p_limit integer default 500)
returns table (id uuid, auth jsonb, profile jsonb, mfa_enabled boolean)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  return query
    select
      u.id,
      jsonb_build_object(
        'email',              u.email,
        'phone',              u.phone,
        'encrypted_password', u.encrypted_password,
        'email_confirmed_at', u.email_confirmed_at,
        'last_sign_in_at',    u.last_sign_in_at,
        'banned_until',       u.banned_until,
        'created_at',         u.created_at,
        'updated_at',         u.updated_at,
        'is_anonymous',       coalesce((to_jsonb(u) ->> 'is_anonymous')::boolean, false),
        'providers',          coalesce(u.raw_app_meta_data -> 'providers', '[]'::jsonb),
        'deleted_at',         to_jsonb(u) -> 'deleted_at'
      ),
      to_jsonb(p) - 'id',
      exists (select 1 from auth.mfa_factors f where f.user_id = u.id and f.status = 'verified')
    from auth.users u
    left join public.profiles p on p.id = u.id
    where p_after is null or u.id > p_after
    order by u.id
    limit greatest(1, least(coalesce(p_limit, 500), 1000));
end;
$$;

revoke execute on function public.vdl_export_accounts(uuid, integer) from public, anon, authenticated;
grant execute on function public.vdl_export_accounts(uuid, integer) to service_role;

-- quick count so the console can show progress
create or replace function public.vdl_export_count()
returns bigint language sql stable security definer set search_path = '' as $$
  select count(*) from auth.users;
$$;
revoke execute on function public.vdl_export_count() from public, anon, authenticated;
grant execute on function public.vdl_export_count() to service_role;

notify pgrst, 'reload schema';

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- 20261104020000_memories.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- Memories (20261104020000)
--
-- Story-style photos / short videos pinned to your profile.
--   * up to 10 memories per account at a time (enforced here, not just in the UI)
--   * videos up to 30 seconds
--   * visible to the same people who can see your profile (shared server / DM,
--     friends, staff) and never to anyone either side has blocked
--   * the owner can see who viewed each memory
--   * media lives in a PRIVATE bucket and is read through short-lived signed URLs
--
-- Safe to run more than once.
-- =============================================================================

create table if not exists public.memories (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references public.profiles (id) on delete cascade,
  path         text not null check (char_length(path) between 10 and 300),
  media_type   text not null check (media_type in ('image', 'video')),
  duration_ms  integer not null default 6000 check (duration_ms between 1000 and 30000),
  caption      text not null default '' check (char_length(caption) <= 200),
  width        integer check (width between 1 and 8192),
  height       integer check (height between 1 and 8192),
  created_at   timestamptz not null default now()
);
create index if not exists memories_user_idx on public.memories (user_id, created_at);
alter table public.memories enable row level security;

create table if not exists public.memory_views (
  memory_id  uuid not null references public.memories (id) on delete cascade,
  viewer_id  uuid not null references public.profiles (id) on delete cascade,
  seen_at    timestamptz not null default now(),
  primary key (memory_id, viewer_id)
);
alter table public.memory_views enable row level security;

-- media path must live in the owner's own folder: <user_id>/<file>
create or replace function public.guard_memory()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if split_part(new.path, '/', 1) <> new.user_id::text then
    raise exception 'memory media must be stored in your own folder';
  end if;
  perform pg_advisory_xact_lock(hashtext('memories:' || new.user_id::text));
  if (select count(*) from public.memories where user_id = new.user_id) >= 10 then
    raise exception 'You can have up to 10 memories at a time. Delete one to add another.';
  end if;
  return new;
end;
$$;
drop trigger if exists memories_guard on public.memories;
create trigger memories_guard before insert on public.memories
  for each row execute function public.guard_memory();

create or replace function public.can_see_memories(p_owner uuid, p_user uuid default auth.uid())
returns boolean language sql stable security definer set search_path = '' as $$
  select p_user is not null and (
    p_owner = p_user
    or (public.can_see_profile(p_owner, p_user) and not public.is_blocked_between(p_owner, p_user))
  );
$$;
revoke execute on function public.can_see_memories(uuid, uuid) from public, anon;
grant execute on function public.can_see_memories(uuid, uuid) to authenticated;

drop policy if exists memories_select on public.memories;
create policy memories_select on public.memories for select to authenticated
  using (public.can_see_memories(user_id));
drop policy if exists memories_insert on public.memories;
create policy memories_insert on public.memories for insert to authenticated
  with check (user_id = auth.uid());
drop policy if exists memories_delete on public.memories;
create policy memories_delete on public.memories for delete to authenticated
  using (user_id = auth.uid() or public.is_staff());
drop policy if exists memories_update on public.memories;
create policy memories_update on public.memories for update to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());
grant select, insert, delete on public.memories to authenticated;
grant update (caption) on public.memories to authenticated;

drop policy if exists memory_views_insert on public.memory_views;
create policy memory_views_insert on public.memory_views for insert to authenticated
  with check (viewer_id = auth.uid()
              and exists (select 1 from public.memories m where m.id = memory_id and m.user_id <> auth.uid() and public.can_see_memories(m.user_id)));
drop policy if exists memory_views_select on public.memory_views;
create policy memory_views_select on public.memory_views for select to authenticated
  using (viewer_id = auth.uid()
         or exists (select 1 from public.memories m where m.id = memory_id and m.user_id = auth.uid()));
grant select, insert on public.memory_views to authenticated;

-- ----------------------------------------------------------------- storage --
insert into storage.buckets (id, name, public, file_size_limit)
values ('memories', 'memories', false, 26214400)
on conflict (id) do update set public = false, file_size_limit = 26214400;
do $$ begin
  update storage.buckets set allowed_mime_types = array['image/png', 'image/jpeg', 'image/gif', 'image/webp', 'video/mp4', 'video/webm', 'video/quicktime'] where id = 'memories';
exception when undefined_column then null; end $$;

drop policy if exists venband_memories_read on storage.objects;
create policy venband_memories_read on storage.objects for select to authenticated
  using (bucket_id = 'memories' and public.can_see_memories(nullif(split_part(name, '/', 1), '')::uuid));
drop policy if exists venband_memories_write on storage.objects;
create policy venband_memories_write on storage.objects for insert to authenticated
  with check (bucket_id = 'memories' and split_part(name, '/', 1) = auth.uid()::text);
drop policy if exists venband_memories_delete on storage.objects;
create policy venband_memories_delete on storage.objects for delete to authenticated
  using (bucket_id = 'memories' and split_part(name, '/', 1) = auth.uid()::text);

notify pgrst, 'reload schema';

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- 20261104030000_vdl_export_one.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- VDL: export ONE account by email (20261104030000)
--
-- Used for "just-in-time" import: the first time someone signs in to the VDL
-- storage console, their account is pulled from Supabase on the spot, so owners
-- can get in before the first full sync has run. service_role only.
-- Safe to run more than once.
-- =============================================================================

drop function if exists public.vdl_export_account(text);
create function public.vdl_export_account(p_email text)
returns table (id uuid, auth jsonb, profile jsonb, mfa_enabled boolean)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  return query
    select
      u.id,
      jsonb_build_object(
        'email',              u.email,
        'phone',              u.phone,
        'encrypted_password', u.encrypted_password,
        'email_confirmed_at', u.email_confirmed_at,
        'last_sign_in_at',    u.last_sign_in_at,
        'banned_until',       u.banned_until,
        'created_at',         u.created_at,
        'updated_at',         u.updated_at,
        'is_anonymous',       coalesce((to_jsonb(u) ->> 'is_anonymous')::boolean, false),
        'providers',          coalesce(u.raw_app_meta_data -> 'providers', '[]'::jsonb),
        'deleted_at',         to_jsonb(u) -> 'deleted_at'
      ),
      to_jsonb(p) - 'id',
      exists (select 1 from auth.mfa_factors f where f.user_id = u.id and f.status = 'verified')
    from auth.users u
    left join public.profiles p on p.id = u.id
    where lower(u.email) = lower(btrim(p_email))
    limit 1;
end;
$$;

revoke execute on function public.vdl_export_account(text) from public, anon, authenticated;
grant execute on function public.vdl_export_account(text) to service_role;

notify pgrst, 'reload schema';

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- 20261105000000_backfill_profiles.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- Backfill missing profiles (20261105000000)
--
-- Accounts created while the database had no schema (or before the signup
-- trigger existed) have an auth.users row but no public.profiles row. They
-- couldn't sign in ("No account with that username or email") and couldn't
-- sign up again ("There's already an account with that email").
--
--   1. creates a profile for every auth user that lacks one, using the username
--      they picked at signup (or a safe unique one if it's taken/invalid)
--   2. resolve_login now finds an account by email even if its profile is
--      missing, so this can't lock anyone out again (my_profile() then
--      creates the profile on first sign-in)
--
-- Safe to run more than once.
-- =============================================================================

-- 1. backfill -------------------------------------------------------------------
do $$
declare
  r record;
  v_wanted text;
  v_name text;
  v_display text;
  v_count integer := 0;
begin
  for r in
    select u.id, u.email, u.raw_user_meta_data as meta
    from auth.users u
    where not exists (select 1 from public.profiles p where p.id = u.id)
    order by u.created_at nulls last
  loop
    v_wanted := lower(btrim(coalesce(r.meta ->> 'username', '')));
    if v_wanted ~ '^[a-z0-9_.]{2,32}$' and not exists (select 1 from public.profiles where username = v_wanted) then
      v_name := v_wanted;
    else
      v_name := public.unique_username(coalesce(nullif(v_wanted, ''), split_part(coalesce(r.email, ''), '@', 1)));
    end if;
    v_display := left(coalesce(nullif(btrim(r.meta ->> 'display_name'), ''), v_name), 32);
    insert into public.profiles (id, username, display_name)
    values (r.id, v_name, v_display)
    on conflict (id) do nothing;
    v_count := v_count + 1;
  end loop;
  raise notice 'created % missing profile(s)', v_count;
end $$;

-- 2. resolve_login: email lookups no longer require a profile --------------------
drop function if exists public.resolve_login(text);
create function public.resolve_login(p_identifier text)
returns table (email text, username text, banned boolean)
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_headers    text;
  v_ip         text := '';
  v_attempts   integer;
  v_identifier text := lower(btrim(coalesce(p_identifier, '')));
begin
  if v_identifier = '' then return; end if;

  begin
    v_headers := current_setting('request.headers', true);
    if v_headers is not null and v_headers <> '' then
      v_ip := btrim(coalesce(
        nullif(split_part(coalesce(v_headers::json ->> 'x-forwarded-for', ''), ',', 1), ''),
        nullif(v_headers::json ->> 'cf-connecting-ip', ''),
        ''
      ));
    end if;
  exception when others then
    v_ip := '';
  end;

  if v_ip <> '' then
    delete from public.login_lookups where attempted_at < now() - interval '1 day';
    select count(*) into v_attempts
      from public.login_lookups
     where ip = v_ip and attempted_at > now() - interval '10 minutes';
    if v_attempts >= 20 then
      raise exception 'Too many login attempts. Please wait a few minutes and try again.';
    end if;
    insert into public.login_lookups (ip, identifier_hash) values (v_ip, md5(v_identifier));
  end if;

  if position('@' in v_identifier) > 0 then
    return query
      select u.email::text,
             coalesce(p.username, split_part(u.email, '@', 1))::text,
             ((u.banned_until is not null and u.banned_until > now()) or coalesce(p.account_status, 'active') = 'banned')
        from auth.users u
        left join public.profiles p on p.id = u.id
       where lower(u.email) = v_identifier
       limit 1;
  elsif v_identifier ~ '^[a-z0-9_.]{2,32}$' then
    return query
      select u.email::text,
             p.username::text,
             ((u.banned_until is not null and u.banned_until > now()) or p.account_status = 'banned')
        from public.profiles p
        join auth.users u on u.id = p.id
       where p.username = v_identifier
       limit 1;
  end if;
end;
$$;

revoke execute on function public.resolve_login(text) from public;
grant execute on function public.resolve_login(text) to anon, authenticated;

notify pgrst, 'reload schema';

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- 20261105010000_schema_check.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- Schema check (20261105010000)
--
-- schema_missing(tables, functions, bodies) reports which public tables and
-- functions do NOT exist, and which rewritten functions still have an OLD body.
-- The /status page sends the list from src/lib/schemaManifest.ts (generated
-- from supabase/migrations/), so it can name exactly which migration files a
-- database is missing instead of showing "Operational" for a half-set-up one.
--
-- bodies: {"function_name": "md5 of the newest body with whitespace removed"}.
-- A function counts as current if ANY overload with that name matches.
--
-- Only reveals existence/fingerprints of objects in the public schema, which is
-- already public in the open-source repo. Callable signed out (the status page
-- works without an account). Safe to run more than once.
-- =============================================================================

drop function if exists public.schema_missing(text[], text[]);
drop function if exists public.schema_missing(text[], text[], jsonb);
create function public.schema_missing(p_tables text[] default '{}', p_functions text[] default '{}', p_bodies jsonb default '{}')
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_tables text[];
  v_functions text[];
  v_bodies text[];
begin
  if jsonb_typeof(coalesce(p_bodies, '{}'::jsonb)) <> 'object' then
    raise exception 'bodies must be a JSON object';
  end if;
  if coalesce(cardinality(p_tables), 0) + coalesce(cardinality(p_functions), 0)
     + (select count(*) from jsonb_object_keys(coalesce(p_bodies, '{}'::jsonb))) > 2000 then
    raise exception 'too many objects';
  end if;

  select coalesce(array_agg(t order by t), '{}') into v_tables
    from unnest(coalesce(p_tables, '{}')) t
   where t !~ '^[a-z0-9_]{1,63}$'
      or not exists (select 1 from pg_catalog.pg_class c
                     join pg_catalog.pg_namespace n on n.oid = c.relnamespace
                     where n.nspname = 'public' and c.relname = t and c.relkind in ('r', 'p', 'v', 'm'));

  select coalesce(array_agg(f order by f), '{}') into v_functions
    from unnest(coalesce(p_functions, '{}')) f
   where f !~ '^[a-z0-9_]{1,63}$'
      or not exists (select 1 from pg_catalog.pg_proc p
                     join pg_catalog.pg_namespace n on n.oid = p.pronamespace
                     where n.nspname = 'public' and p.proname = f);

  select coalesce(array_agg(b.key order by b.key), '{}') into v_bodies
    from jsonb_each_text(coalesce(p_bodies, '{}'::jsonb)) b
   where b.key !~ '^[a-z0-9_]{1,63}$'
      or not exists (select 1 from pg_catalog.pg_proc p
                     join pg_catalog.pg_namespace n on n.oid = p.pronamespace
                     where n.nspname = 'public' and p.proname = b.key
                       and md5(regexp_replace(p.prosrc, '[ \t\r\n\f\v]+', '', 'g')) = b.value);

  return jsonb_build_object('tables', to_jsonb(v_tables), 'functions', to_jsonb(v_functions), 'bodies', to_jsonb(v_bodies));
end;
$$;

revoke execute on function public.schema_missing(text[], text[], jsonb) from public;
grant execute on function public.schema_missing(text[], text[], jsonb) to anon, authenticated;

notify pgrst, 'reload schema';

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- 20261105020000_lock_down_internal.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- Lock down internal helpers (20261105020000)
--
-- Supabase exposes every function in `public` through the API unless EXECUTE is
-- revoked. These SECURITY DEFINER helpers are only meant to be called from other
-- database functions (or cron), never by the app — but anyone could call them:
--
--   * wordle_command(app, channel, ...)  — signed-out callers could make any bot
--     post into ANY channel (no membership or permission check). Proven in a test
--     database: an anonymous call added a bot message to a private channel.
--   * are_friends(a, b), is_blocked_between(a, b), shares_server_or_dm(a, b) —
--     anyone signed in could map other people's friendships and blocks.
--   * channel_perm_for_user(channel, user) — signed-out callers could read any
--     user's permissions in any channel.
--   * venband_notice(...) — any staff member could send an *official Venband* DM
--     with arbitrary text, bypassing the moderation flow and its audit log.
--   * the rest are internal helpers with no reason to be public.
--
-- Revoking is safe: none of these is referenced by an RLS policy, check
-- constraint, column default or caller-privilege function (verified against the
-- full schema), and the app never calls them. The functions that call them are
-- SECURITY DEFINER, so they keep working. Cron jobs run as the owner.
--
-- Also: wordle_games (holds each channel's ANSWER) and wordle_words had no RLS,
-- so on Supabase anyone could read today's answers or edit games through the API.
-- They are only used inside wordle_command, so direct access is closed entirely.
--
-- Safe to run more than once.
-- =============================================================================

-- Wordle tables: no direct API access (RLS on, no policies, no grants)
alter table if exists public.wordle_games enable row level security;
alter table if exists public.wordle_words enable row level security;
do $$ begin
  revoke all on public.wordle_games from anon, authenticated;
  revoke all on public.wordle_words from anon, authenticated;
exception when undefined_table then null; end $$;

-- Internal helpers: callable only by the database itself
do $$
declare
  fn text;
begin
  foreach fn in array array[
    'public.wordle_command(uuid, uuid, text, text)',
    'public.wordle_feedback(text, text)',
    'public.are_friends(uuid, uuid)',
    'public.is_blocked_between(uuid, uuid)',
    'public.shares_server_or_dm(uuid, uuid)',
    'public.channel_perm_for_user(uuid, uuid)',
    'public.channel_key_recipients(uuid)',
    'public.member_count(uuid)',
    'public.deliver_scheduled_messages()',
    'public.can_ban_media(uuid)',
    'public.can_force_contact(uuid)',
    'public.mod_can_target(uuid)',
    'public.venband_notice(uuid, text, text, uuid)',
    'public.storage_console_stats()',
    'public.storage_list_auth_users()',
    'public.storage_queue_email(text, text, text)',
    'public.storage_ledger_list()',
    'public.storage_ledger_rebuild()'
  ] loop
    if to_regprocedure(fn) is not null then
      execute format('revoke execute on function %s from public, anon, authenticated', fn);
    end if;
  end loop;
end $$;

notify pgrst, 'reload schema';

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- 20261106000000_theme_versions.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- Theme ownership, versions, drafts and honest install counts (20261106000000)
--
-- Marketplace items (themes, CSS, nameplates, name styles) can now be edited by
-- their creator after publishing — and only by their creator:
--
--   * every publish creates an immutable row in theme_versions (history is never
--     overwritten; existing items are backfilled as version 1)
--   * unpublished changes live in theme_drafts, visible only to the owner
--   * status: draft (never published) / published / unpublished / removed
--     (removed = taken down by Venband staff, with a reason, logged)
--   * there is NO update policy on themes: all changes go through the
--     owner-checked functions below, which re-validate the data server-side with
--     the same rules the app's sanitizers use (themes are colour data only; CSS
--     may not import, load remote files or use script-like tricks)
--   * install counts come from theme_installs (one row per person), so calling
--     install_theme() repeatedly can no longer inflate them; the creator's own
--     installs don't count. Existing counts are kept as a baseline.
--   * older app versions that insert directly still work: their inserts are
--     validated and recorded as a published version 1.
--
-- Safe to run more than once.
-- =============================================================================

-- ------------------------------------------------------------------ columns --
alter table public.themes
  add column if not exists status text not null default 'published',
  add column if not exists version integer not null default 1,
  add column if not exists updated_at timestamptz not null default now(),
  add column if not exists category text,
  add column if not exists removed_reason text,
  add column if not exists legacy_installs integer not null default 0;

do $$ begin
  alter table public.themes add constraint themes_status_check check (status in ('draft', 'published', 'unpublished', 'removed'));
exception when duplicate_object then null; end $$;
do $$ begin
  alter table public.themes add constraint themes_version_check check (version >= 0);
exception when duplicate_object then null; end $$;
do $$ begin
  alter table public.themes add constraint themes_category_check
    check (category is null or category in ('dark', 'light', 'colorful', 'minimal', 'glass', 'high-contrast', 'seasonal', 'other'));
exception when duplicate_object then null; end $$;
do $$ begin
  alter table public.themes add constraint themes_removed_reason_check check (removed_reason is null or char_length(removed_reason) <= 500);
exception when duplicate_object then null; end $$;

create index if not exists themes_status_kind_idx on public.themes (status, kind, installs desc);
create index if not exists themes_author_idx on public.themes (author_id, updated_at desc);

-- ------------------------------------------------------------------- tables --
create table if not exists public.theme_versions (
  theme_id     uuid not null references public.themes (id) on delete cascade,
  version      integer not null check (version >= 1),
  name         text not null check (char_length(btrim(name)) between 1 and 40),
  description  text not null default '' check (char_length(description) <= 140),
  category     text,
  data         jsonb not null check (pg_column_size(data) < 20000),
  changelog    text not null default '' check (char_length(changelog) <= 500),
  published_by uuid references public.profiles (id) on delete set null,
  created_at   timestamptz not null default now(),
  primary key (theme_id, version)
);
alter table public.theme_versions enable row level security;

create table if not exists public.theme_drafts (
  theme_id    uuid primary key references public.themes (id) on delete cascade,
  name        text not null check (char_length(btrim(name)) between 1 and 40),
  description text not null default '' check (char_length(description) <= 140),
  category    text,
  data        jsonb not null check (pg_column_size(data) < 20000),
  updated_at  timestamptz not null default now()
);
alter table public.theme_drafts enable row level security;

create table if not exists public.theme_installs (
  theme_id     uuid not null references public.themes (id) on delete cascade,
  user_id      uuid not null references public.profiles (id) on delete cascade,
  version      integer not null default 1,
  installed_at timestamptz not null default now(),
  primary key (theme_id, user_id)
);
create index if not exists theme_installs_user_idx on public.theme_installs (user_id);
alter table public.theme_installs enable row level security;

-- ----------------------------------------------------------------- backfill --
insert into public.theme_versions (theme_id, version, name, description, category, data, changelog, published_by, created_at)
select t.id, 1, t.name, t.description, t.category, t.data, '', t.author_id, t.created_at
  from public.themes t
 where t.status <> 'draft'
on conflict do nothing;

-- keep the install counts people already earned (they can't be re-derived)
update public.themes t set legacy_installs = t.installs
 where t.legacy_installs = 0 and t.installs > 0
   and not exists (select 1 from public.theme_installs i where i.theme_id = t.id);

-- ---------------------------------------------------------------- validation --
-- Returns NULL when the data is acceptable, otherwise a human-readable reason.
-- Mirrors sanitizeTheme() (src/lib/themes.ts) and sanitizeCss() (src/lib/customCss.ts).
create or replace function public.theme_data_problem(p_kind text, p_data jsonb)
returns text language plpgsql immutable set search_path = '' as $$
declare
  k text;
  v jsonb;
  css text;
  color_re constant text := '^(#[0-9a-fA-F]{3,8}|rgba?\([0-9\s.,%]+\)|hsla?\([0-9\s.,%deg]+\))$';
  grad_re  constant text := '^((radial|linear|conic)-gradient\([#\w\s.,%()-]+\)\s*,?\s*)+$';
  theme_keys constant text[] := array['bg-0', 'bg-1', 'bg-2', 'bg-3', 'bg-4', 'bg-hover', 'line', 'line-2', 'text', 'text-2',
    'muted', 'accent', 'accent-hover', 'accent-soft', 'accent-text', 'on-accent', 'link', 'success', 'danger', 'warning', 'mention-bg'];
begin
  if p_data is null or jsonb_typeof(p_data) <> 'object' then return 'data must be a JSON object'; end if;
  if pg_column_size(p_data) >= 20000 then return 'that is too big to publish'; end if;

  if p_kind = 'theme' then
    for k in select jsonb_object_keys(p_data) loop
      if k <> all (array['id', 'name', 'description', 'vars', 'glass', 'wallpaper', 'author', 'version', 'sourceId']) then
        return 'unknown theme field: ' || k;
      end if;
    end loop;
    if jsonb_typeof(p_data -> 'vars') is distinct from 'object' then return 'a theme needs colour variables'; end if;
    for k, v in select e.key, e.value from jsonb_each(p_data -> 'vars') e loop
      if k <> all (theme_keys) then return 'unknown colour variable: ' || k; end if;
      if jsonb_typeof(v) <> 'string' or btrim(v #>> '{}') !~ color_re then return 'invalid colour for ' || k; end if;
    end loop;
    if p_data ? 'wallpaper' and jsonb_typeof(p_data -> 'wallpaper') <> 'null'
       and (jsonb_typeof(p_data -> 'wallpaper') <> 'string' or btrim(p_data ->> 'wallpaper') !~ grad_re) then
      return 'the wallpaper must be a CSS gradient';
    end if;
    if p_data ? 'glass' and jsonb_typeof(p_data -> 'glass') not in ('boolean', 'null') then return 'glass must be true or false'; end if;

  elsif p_kind = 'css' then
    for k in select jsonb_object_keys(p_data) loop
      if k <> 'css' then return 'unknown CSS field: ' || k; end if;
    end loop;
    if jsonb_typeof(p_data -> 'css') is distinct from 'string' then return 'the CSS must be text'; end if;
    css := p_data ->> 'css';
    if char_length(css) > 16000 then return 'CSS is limited to 16,000 characters'; end if;
    css := regexp_replace(css, '/\*.*?\*/', '', 'g'); -- comments can't do anything
    if css ~* '@import|@charset|expression\s*\(|behavior\s*:|-moz-binding|javascript\s*:|image-set\(|<\s*/?\s*style' then
      return 'the CSS contains blocked code (imports, scripts or remote files)';
    end if;
    if css ~* 'url\(\s*[''"]?\s*(?!data:image/(png|jpe?g|gif|webp|svg\+xml);)' then
      return 'CSS may only use pictures embedded as data:image URLs';
    end if;

  elsif p_kind in ('nameplate', 'name_style') then
    for k in select jsonb_object_keys(p_data) loop
      if (p_kind = 'nameplate' and k <> all (array['colors', 'pattern']))
         or (p_kind = 'name_style' and k <> all (array['colors', 'font', 'effect'])) then
        return 'unknown field: ' || k;
      end if;
    end loop;
    if p_data ? 'colors' and jsonb_typeof(p_data -> 'colors') <> 'null' then
      if jsonb_typeof(p_data -> 'colors') <> 'array' or jsonb_array_length(p_data -> 'colors') > 3 then return 'up to 3 colours'; end if;
      if exists (select 1 from jsonb_array_elements(p_data -> 'colors') c
                 where jsonb_typeof(c) <> 'string' or (c #>> '{}') !~ '^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})$') then
        return 'colours must be hex, like #rrggbb';
      end if;
    end if;
    foreach k in array array['pattern', 'font', 'effect'] loop
      if p_data ? k and jsonb_typeof(p_data -> k) <> 'null'
         and (jsonb_typeof(p_data -> k) <> 'string' or (p_data ->> k) !~ '^[a-z0-9_-]{1,24}$') then
        return 'invalid ' || k;
      end if;
    end loop;

  else
    return 'unknown kind of item';
  end if;
  return null;
end;
$$;

-- --------------------------------------------------------- insert guard/history --
-- Direct inserts (older app versions) are always a validated, published version 1.
create or replace function public.guard_theme_insert()
returns trigger language plpgsql security definer set search_path = '' as $$
declare v_problem text;
begin
  if coalesce(current_setting('venband.theme_fn', true), '') <> 'on' then
    new.status := 'published';
    new.version := 1;
    new.installs := 0;
    new.legacy_installs := 0;
    new.removed_reason := null;
    v_problem := public.theme_data_problem(new.kind, new.data);
    if v_problem is not null then raise exception '%', v_problem; end if;
  end if;
  new.updated_at := now();
  return new;
end;
$$;
drop trigger if exists themes_guard_insert on public.themes;
create trigger themes_guard_insert before insert on public.themes
  for each row execute function public.guard_theme_insert();

create or replace function public.theme_first_version()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.status = 'published' and new.version = 1 then
    insert into public.theme_versions (theme_id, version, name, description, category, data, changelog, published_by, created_at)
    values (new.id, 1, new.name, new.description, new.category, new.data, '', new.author_id, new.created_at)
    on conflict do nothing;
  end if;
  return null;
end;
$$;
drop trigger if exists themes_first_version on public.themes;
create trigger themes_first_version after insert on public.themes
  for each row execute function public.theme_first_version();

-- ------------------------------------------------------------------ helpers --
create or replace function public.theme_categories()
returns text[] language sql immutable set search_path = '' as $$
  select array['dark', 'light', 'colorful', 'minimal', 'glass', 'high-contrast', 'seasonal', 'other']::text[];
$$;

-- -------------------------------------------------------------- theme_save --
-- Create a new draft item (p_theme null) or save changes to your own item as a
-- draft. Nothing is visible to anyone else until theme_publish().
create or replace function public.theme_save(
  p_theme uuid, p_kind text, p_name text, p_description text, p_data jsonb, p_category text default null)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  v_id uuid := p_theme;
  v_kind text := p_kind;
  v_problem text;
  t public.themes%rowtype;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  if char_length(btrim(coalesce(p_name, ''))) not between 1 and 40 then raise exception 'the name must be 1–40 characters'; end if;
  if char_length(coalesce(p_description, '')) > 140 then raise exception 'the description is limited to 140 characters'; end if;
  if p_category is not null and p_category <> all (public.theme_categories()) then raise exception 'unknown category'; end if;

  if v_id is null then
    if not public.account_can('publish') then raise exception 'your account can''t publish right now'; end if;
    if (select count(*) from public.themes where author_id = v_uid) >= 25 then
      raise exception 'you can have up to 25 items (published or drafts) — delete one first';
    end if;
    v_problem := public.theme_data_problem(v_kind, p_data);
    if v_problem is not null then raise exception '%', v_problem; end if;
    perform set_config('venband.theme_fn', 'on', true);
    insert into public.themes (author_id, kind, name, description, data, status, version, category, installs)
    values (v_uid, v_kind, btrim(p_name), coalesce(p_description, ''), p_data, 'draft', 0, p_category, 0)
    returning id into v_id;
    perform set_config('venband.theme_fn', 'off', true);
  else
    select * into t from public.themes where id = v_id for update;
    if not found then raise exception 'not found'; end if;
    if t.author_id <> v_uid then raise exception 'only the creator can edit this'; end if;
    if t.status = 'removed' then raise exception 'this was removed by Venband moderators and can''t be edited'; end if;
    if v_kind is not null and v_kind <> t.kind then raise exception 'you can''t change what kind of item this is'; end if;
    v_kind := t.kind;
    v_problem := public.theme_data_problem(v_kind, p_data);
    if v_problem is not null then raise exception '%', v_problem; end if;
  end if;

  insert into public.theme_drafts (theme_id, name, description, category, data, updated_at)
  values (v_id, btrim(p_name), coalesce(p_description, ''), p_category, p_data, now())
  on conflict (theme_id) do update
    set name = excluded.name, description = excluded.description, category = excluded.category,
        data = excluded.data, updated_at = now();
  return v_id;
end;
$$;

-- ----------------------------------------------------------- theme_publish --
-- Publish your draft as a new version. The previous versions stay in history.
create or replace function public.theme_publish(p_theme uuid, p_changelog text default '')
returns integer language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  t public.themes%rowtype;
  d public.theme_drafts%rowtype;
  v_next integer;
  v_problem text;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  select * into t from public.themes where id = p_theme for update;
  if not found then raise exception 'not found'; end if;
  if t.author_id <> v_uid then raise exception 'only the creator can publish this'; end if;
  if t.status = 'removed' then raise exception 'this was removed by Venband moderators'; end if;
  if not public.account_can('publish') then raise exception 'your account can''t publish right now'; end if;
  select * into d from public.theme_drafts where theme_id = p_theme;
  if not found then raise exception 'there are no unpublished changes'; end if;
  if exists (select 1 from public.theme_versions where theme_id = p_theme and created_at > now() - interval '15 seconds') then
    raise exception 'you just published this — wait a few seconds';
  end if;
  v_problem := public.theme_data_problem(t.kind, d.data);
  if v_problem is not null then raise exception '%', v_problem; end if;

  v_next := t.version + 1;
  insert into public.theme_versions (theme_id, version, name, description, category, data, changelog, published_by)
  values (p_theme, v_next, d.name, d.description, d.category, d.data, left(btrim(coalesce(p_changelog, '')), 500), v_uid);
  update public.themes
     set name = d.name, description = d.description, category = d.category, data = d.data,
         version = v_next, status = 'published', updated_at = now()
   where id = p_theme;
  delete from public.theme_drafts where theme_id = p_theme;
  return v_next;
end;
$$;

-- ---------------------------------------------------------- theme_rollback --
-- Make an older version current again. History stays linear: the old version is
-- republished as a NEW version, so people who installed it see a normal update.
create or replace function public.theme_rollback(p_theme uuid, p_version integer)
returns integer language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  t public.themes%rowtype;
  v public.theme_versions%rowtype;
  v_next integer;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  select * into t from public.themes where id = p_theme for update;
  if not found then raise exception 'not found'; end if;
  if t.author_id <> v_uid then raise exception 'only the creator can restore versions'; end if;
  if t.status = 'removed' then raise exception 'this was removed by Venband moderators'; end if;
  select * into v from public.theme_versions where theme_id = p_theme and version = p_version;
  if not found then raise exception 'that version doesn''t exist'; end if;
  if p_version = t.version then raise exception 'that is already the current version'; end if;
  if exists (select 1 from public.theme_versions where theme_id = p_theme and created_at > now() - interval '15 seconds') then
    raise exception 'you just published this — wait a few seconds';
  end if;
  v_next := t.version + 1;
  insert into public.theme_versions (theme_id, version, name, description, category, data, changelog, published_by)
  values (p_theme, v_next, v.name, v.description, v.category, v.data, 'Restored version ' || p_version, v_uid);
  update public.themes
     set name = v.name, description = v.description, category = v.category, data = v.data,
         version = v_next, updated_at = now()
   where id = p_theme;
  return v_next;
end;
$$;

-- -------------------------------------------------------- theme_set_status --
-- Owner: publish / unpublish their own item. Staff: remove (with a reason) or
-- restore anyone's item; every staff action is written to mod_actions.
create or replace function public.theme_set_status(p_theme uuid, p_status text, p_reason text default '')
returns void language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  t public.themes%rowtype;
  v_staff boolean := public.is_staff();
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  if p_status not in ('published', 'unpublished', 'removed') then raise exception 'unknown status'; end if;
  select * into t from public.themes where id = p_theme for update;
  if not found then raise exception 'not found'; end if;

  if p_status = 'removed' or t.status = 'removed' then
    if not v_staff then raise exception 'only Venband staff can remove or restore marketplace items'; end if;
    if p_status = 'removed' and char_length(btrim(coalesce(p_reason, ''))) < 3 then raise exception 'give a reason for removing it'; end if;
    if p_status <> 'removed' and t.version < 1 then raise exception 'it was never published'; end if;
    update public.themes
       set status = p_status, updated_at = now(),
           removed_reason = case when p_status = 'removed' then left(btrim(p_reason), 500) else null end
     where id = p_theme;
    insert into public.mod_actions (actor_id, target_user, action, detail, reason)
    values (v_uid, t.author_id, 'marketplace_' || case when p_status = 'removed' then 'remove' else 'restore' end,
            t.kind || ' “' || t.name || '” (' || t.id || ')', left(coalesce(p_reason, ''), 1000));
    return;
  end if;

  if t.author_id <> v_uid then raise exception 'only the creator can change this'; end if;
  if p_status = 'published' and t.version < 1 then raise exception 'publish it first'; end if;
  update public.themes set status = p_status, updated_at = now() where id = p_theme;
end;
$$;

-- -------------------------------------------------------- installs (honest) --
create or replace function public.install_theme(p_theme uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare t public.themes%rowtype;
begin
  if auth.uid() is null then return; end if;
  select * into t from public.themes where id = p_theme and status = 'published';
  if not found then raise exception 'that item isn''t available any more'; end if;
  if t.author_id = auth.uid() then return; end if; -- your own installs don't count
  insert into public.theme_installs (theme_id, user_id, version) values (p_theme, auth.uid(), greatest(t.version, 1))
  on conflict (theme_id, user_id) do update set version = excluded.version, installed_at = now();
  update public.themes
     set installs = legacy_installs + (select count(*) from public.theme_installs where theme_id = p_theme)
   where id = p_theme;
end;
$$;

create or replace function public.uninstall_theme(p_theme uuid)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if auth.uid() is null then return; end if;
  delete from public.theme_installs where theme_id = p_theme and user_id = auth.uid();
  if found then
    update public.themes
       set installs = legacy_installs + (select count(*) from public.theme_installs where theme_id = p_theme)
     where id = p_theme;
  end if;
end;
$$;

-- -------------------------------------------------------------- RLS policies --
drop policy if exists themes_select on public.themes;
create policy themes_select on public.themes for select to authenticated
  using (status = 'published' or author_id = auth.uid() or public.is_staff());

drop policy if exists theme_versions_select on public.theme_versions;
create policy theme_versions_select on public.theme_versions for select to authenticated
  using (exists (select 1 from public.themes t where t.id = theme_id
                 and (t.status = 'published' or t.author_id = auth.uid() or public.is_staff())));

drop policy if exists theme_drafts_select on public.theme_drafts;
create policy theme_drafts_select on public.theme_drafts for select to authenticated
  using (exists (select 1 from public.themes t where t.id = theme_id and t.author_id = auth.uid()));

drop policy if exists theme_installs_select on public.theme_installs;
create policy theme_installs_select on public.theme_installs for select to authenticated
  using (user_id = auth.uid());

-- ------------------------------------------------------------------- grants --
-- Reads only: every write goes through the functions above.
revoke all on public.theme_versions, public.theme_drafts, public.theme_installs from anon, authenticated;
grant select on public.theme_versions, public.theme_drafts, public.theme_installs to authenticated;

do $$
declare fn text;
begin
  foreach fn in array array[
    'public.theme_save(uuid, text, text, text, jsonb, text)',
    'public.theme_publish(uuid, text)',
    'public.theme_rollback(uuid, integer)',
    'public.theme_set_status(uuid, text, text)',
    'public.install_theme(uuid)',
    'public.uninstall_theme(uuid)',
    'public.theme_categories()'
  ] loop
    execute format('revoke execute on function %s from public, anon', fn);
    execute format('grant execute on function %s to authenticated', fn);
  end loop;
  foreach fn in array array['public.guard_theme_insert()', 'public.theme_first_version()'] loop
    execute format('revoke execute on function %s from public, anon, authenticated', fn);
  end loop;
end $$;

notify pgrst, 'reload schema';

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- 20261106010000_official_notifications.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- Official notifications + security alerts (20261106010000)
--
--   * public.notifications: the notification center. Rows are created ONLY by the
--     database (SECURITY DEFINER functions/triggers below) — the API can read your
--     own and mark them read, never create, edit or delete them. Deleting the DM
--     with Venband doesn't remove a notification.
--   * public.notify(): the one way to notify someone. Optionally also sends the
--     official Venband DM. Deduplicates, and caps DMs so nobody gets spammed.
--     Not callable through the API.
--   * Real events that notify:
--       security   — new sign-in (device_sessions), device signed out, password
--                    changed/reset, email changed, two-factor on/off (auth triggers)
--       moderation — account limited / restricted / banned (venband_notice), and
--                    restrictions lifted (profile status trigger)
--       platform   — marketplace item removed / restored by staff
--       community  — your report was reviewed
--   * Official identity can't be faked: only the fixed system account may name an
--     app "Venband"/"Official" (the 'venband' moderation-toolkit preset stays open
--     to everyone), and other bots/webhooks can't post under such a display name
--     (it's dropped). The app marks official messages by the app's OWNER (server
--     data), never by a name or preset.
--
-- Safe to run more than once.
-- =============================================================================

-- ------------------------------------------------------------- the table --
create table if not exists public.notifications (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references public.profiles (id) on delete cascade,
  category   text not null check (category in ('security', 'moderation', 'platform', 'community')),
  kind       text not null check (kind ~ '^[a-z_]{2,40}$'),
  severity   text not null default 'info' check (severity in ('info', 'warning', 'critical')),
  title      text not null check (char_length(title) between 1 and 160),
  body       text not null default '' check (char_length(body) <= 2000),
  data       jsonb not null default '{}'::jsonb check (jsonb_typeof(data) = 'object' and pg_column_size(data) < 8000),
  created_at timestamptz not null default now(),
  read_at    timestamptz
);
create index if not exists notifications_user_idx on public.notifications (user_id, created_at desc);
create index if not exists notifications_unread_idx on public.notifications (user_id) where read_at is null;
alter table public.notifications enable row level security;

drop policy if exists notifications_select on public.notifications;
create policy notifications_select on public.notifications for select to authenticated
  using (user_id = auth.uid());
drop policy if exists notifications_update on public.notifications;
create policy notifications_update on public.notifications for update to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());

revoke all on public.notifications from anon, authenticated;
grant select on public.notifications to authenticated;
grant update (read_at) on public.notifications to authenticated;

do $$ begin
  if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'notifications') then
    alter publication supabase_realtime add table public.notifications;
  end if;
exception when undefined_object then raise notice 'no supabase_realtime publication; live notification updates disabled';
end $$;

-- ------------------------------------------------------------ official DM --
-- Posts an embed from the official Venband account into its DM with the user.
-- Internal only: no staff check because the database calls it for system events.
create or replace function public.official_dm(p_user uuid, p_title text, p_body text, p_color text default '#5865f2',
                                              p_fields jsonb default '[]'::jsonb, p_footer text default null)
returns void language plpgsql security definer set search_path = '' as $$
declare
  v_venband constant uuid := '3fff0000-0000-4000-8000-0000000000bd';
  v_channel uuid;
  v_app uuid;
begin
  if p_user is null or p_user = v_venband then return; end if;
  if not exists (select 1 from public.profiles where id = p_user) then return; end if;
  select id into v_app from public.applications where owner_id = v_venband and preset = 'venband' order by created_at limit 1;
  if v_app is null then return; end if;
  select a.channel_id into v_channel
    from public.dm_participants a
    join public.dm_participants b on a.channel_id = b.channel_id
    join public.channels c on c.id = a.channel_id and not c.is_group
   where a.user_id = v_venband and b.user_id = p_user
   limit 1;
  if v_channel is null then
    insert into public.channels (type, name) values ('dm', 'dm') returning id into v_channel;
    insert into public.dm_participants (channel_id, user_id) values (v_channel, v_venband), (v_channel, p_user);
  end if;
  insert into public.bot_messages (channel_id, app_id, username, content, embed)
  values (v_channel, v_app, 'Venband', '',
          jsonb_build_object('title', left(p_title, 256), 'description', left(coalesce(p_body, ''), 2000),
                             'color', coalesce(p_color, '#5865f2'), 'fields', coalesce(p_fields, '[]'::jsonb),
                             'footer', coalesce(p_footer, 'Official Venband notice · verify it in Settings → Security → Official notices')));
end;
$$;

-- ----------------------------------------------------------------- notify --
create or replace function public.notify(
  p_user uuid, p_category text, p_kind text, p_title text, p_body text default '',
  p_severity text default 'info', p_actions text[] default '{}', p_data jsonb default '{}'::jsonb,
  p_dm boolean default false, p_dm_fields jsonb default '[]'::jsonb, p_dedupe text default null)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  v_id uuid;
  a text;
begin
  if p_user is null or p_user = '3fff0000-0000-4000-8000-0000000000bd' then return null; end if;
  if not exists (select 1 from public.profiles where id = p_user) then return null; end if;
  foreach a in array coalesce(p_actions, '{}') loop
    if a !~ '^[a-z_]{2,32}$' then raise exception 'bad notification action %', a; end if;
  end loop;
  -- the same event (e.g. one sign-in) never notifies twice
  if p_dedupe is not null and exists (
       select 1 from public.notifications
        where user_id = p_user and data ->> 'dedupe' = p_dedupe and created_at > now() - interval '1 day') then
    return null;
  end if;
  insert into public.notifications (user_id, category, kind, severity, title, body, data)
  values (p_user, p_category, p_kind, coalesce(p_severity, 'info'), left(p_title, 160), left(coalesce(p_body, ''), 2000),
          coalesce(p_data, '{}'::jsonb)
            || jsonb_build_object('actions', to_jsonb(coalesce(p_actions, '{}')))
            || case when p_dedupe is null then '{}'::jsonb else jsonb_build_object('dedupe', p_dedupe) end)
  returning id into v_id;
  -- official DMs: at most 10 an hour per person (the notification itself is always kept)
  if p_dm and (select count(*) from public.notifications
                where user_id = p_user and created_at > now() - interval '1 hour' and data ? 'dm') < 10 then
    update public.notifications set data = data || '{"dm": true}'::jsonb where id = v_id;
    perform public.official_dm(p_user, p_title, p_body,
      case p_severity when 'critical' then '#ed4245' when 'warning' then '#faa61a' else '#5865f2' end,
      coalesce(p_dm_fields, '[]'::jsonb));
  end if;
  return v_id;
end;
$$;

create or replace function public.mark_notifications_read(p_ids uuid[] default null)
returns integer language plpgsql security definer set search_path = '' as $$
declare n integer;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  update public.notifications set read_at = now()
   where user_id = auth.uid() and read_at is null and (p_ids is null or id = any (p_ids));
  get diagnostics n = row_count;
  return n;
end;
$$;

-- ---------------------------------------------------- moderation notices --
-- Same messages as before, now also in the notification center.
create or replace function public.venband_notice(p_user uuid, p_status text, p_reason text default '', p_server uuid default null)
returns void language plpgsql security definer set search_path = '' as $$
declare
  v_title text;
  v_body text;
  v_sev text;
  v_fields jsonb := '[]'::jsonb;
  v_server text;
begin
  if not public.is_staff() then raise exception 'staff only'; end if;
  if p_server is not null then
    select name into v_server from public.servers where id = p_server;
    if v_server is not null then v_fields := v_fields || jsonb_build_object('name', 'Server', 'value', v_server); end if;
  end if;
  if p_status = 'banned' then
    v_title := 'Your account was banned';
    v_sev := 'critical';
    v_body := 'You can no longer sign in to Venband. If you think this is a mistake, contact support.';
  elsif p_status = 'very_limited' then
    v_title := 'Your account was restricted';
    v_sev := 'critical';
    v_body := 'Your account is now read-only: no messages, calls, servers, DMs or friend requests for now.';
  elsif p_status = 'limited' then
    v_title := 'Your account was limited';
    v_sev := 'warning';
    v_body := 'Some features are paused: no new servers, no DMs with non-friends and no friend requests for now.';
  else
    return;
  end if;
  if coalesce(btrim(p_reason), '') <> '' then
    v_fields := v_fields || jsonb_build_object('name', 'Reason', 'value', left(p_reason, 1000));
  end if;
  perform public.notify(p_user, 'moderation', 'account_' || p_status, v_title, v_body, v_sev, array['view_guidelines'],
    jsonb_build_object('status', p_status, 'reason', nullif(btrim(coalesce(p_reason, '')), ''), 'server', v_server),
    true, v_fields, null);
end;
$$;

create or replace function public.notify_account_restored()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.account_status = 'active' and old.account_status in ('limited', 'very_limited', 'banned') then
    perform public.notify(new.id, 'moderation', 'account_restored', 'Your account restrictions were lifted',
      'Everything works normally again. Thanks for your patience.', 'info', array['view_guidelines'],
      jsonb_build_object('previous', old.account_status), true, '[]'::jsonb, null);
  end if;
  return null;
end;
$$;
drop trigger if exists profiles_status_notify on public.profiles;
create trigger profiles_status_notify after update of account_status on public.profiles
  for each row execute function public.notify_account_restored();

-- --------------------------------------------------------- security events --
-- A new device signed in (the app registers every session in device_sessions).
create or replace function public.notify_new_signin()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  v_where text;
  v_device text := coalesce(nullif(btrim(new.label), ''), 'a new device');
  v_fields jsonb;
begin
  -- the very first device of a brand-new account is just the signup
  if exists (select 1 from public.profiles where id = new.user_id and created_at > now() - interval '30 minutes')
     and not exists (select 1 from public.device_sessions where user_id = new.user_id and session_id <> new.session_id) then
    return null;
  end if;
  v_where := nullif(concat_ws(', ', nullif(btrim(new.city), ''), nullif(btrim(new.region), ''), nullif(btrim(new.country), '')), '');
  v_fields := jsonb_build_array(jsonb_build_object('name', 'Device', 'value', v_device))
              || case when v_where is null then '[]'::jsonb else jsonb_build_array(jsonb_build_object('name', 'Approximate location', 'value', v_where)) end;
  perform public.notify(new.user_id, 'security', 'new_signin', 'New sign-in to your account',
    'Your account was just signed in on ' || v_device || coalesce(' near ' || v_where, '') ||
    '. If this was you, there''s nothing to do. If not, sign that device out and change your password.',
    'warning', array['review_devices', 'secure_account'],
    jsonb_build_object('device', v_device, 'location', v_where), true, v_fields, 'signin:' || new.session_id);
  return null;
end;
$$;
drop trigger if exists device_sessions_notify on public.device_sessions;
create trigger device_sessions_notify after insert on public.device_sessions
  for each row execute function public.notify_new_signin();

-- Signing a device out (Settings → Devices) is recorded too.
create or replace function public.revoke_device(p_session uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare n integer;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  delete from auth.sessions where id = p_session and user_id = auth.uid();
  get diagnostics n = row_count;
  delete from public.device_sessions where session_id = p_session and user_id = auth.uid();
  if n > 0 then
    perform public.notify(auth.uid(), 'security', 'session_revoked', 'A device was signed out',
      'A device was signed out of your account from Settings → Devices.', 'info', array['review_devices'],
      jsonb_build_object('session', p_session), false, '[]'::jsonb, null);
  end if;
end;
$$;

-- Password / email changes (auth.users). Never blocks the change itself.
create or replace function public.notify_auth_change()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  begin
    if new.encrypted_password is distinct from old.encrypted_password and coalesce(old.encrypted_password, '') <> '' then
      perform public.notify(new.id, 'security', 'password_changed', 'Your password was changed',
        'The password for your account was just changed or reset. If you didn''t do this, reset your password now and check your devices.',
        'critical', array['secure_account', 'review_devices'], '{}'::jsonb, true, '[]'::jsonb,
        'password:' || to_char(now(), 'YYYYMMDDHH24MISS'));
    end if;
    if new.email is distinct from old.email and old.email is not null then
      perform public.notify(new.id, 'security', 'email_changed', 'Your email address was changed',
        'Your account’s email is now ' || coalesce(new.email, '(none)') || '. If you didn''t make this change, secure your account now.',
        'critical', array['secure_account'], jsonb_build_object('email', new.email), true, '[]'::jsonb, null);
    end if;
  exception when others then
    raise warning 'notify_auth_change: %', sqlerrm;
  end;
  return null;
end;
$$;

-- Two-factor sign-in turned on / off (auth.mfa_factors).
create or replace function public.notify_mfa_change()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  begin
    if tg_op <> 'DELETE' and new.status = 'verified' and (tg_op = 'INSERT' or old.status is distinct from 'verified') then
      perform public.notify(new.user_id, 'security', 'mfa_enabled', 'Two-factor sign-in was turned on',
        'Signing in now also needs a code from your authenticator app.', 'info', array['secure_account'],
        '{}'::jsonb, true, '[]'::jsonb, 'mfa_on:' || new.id);
    elsif tg_op = 'DELETE' and old.status = 'verified' then
      perform public.notify(old.user_id, 'security', 'mfa_disabled', 'Two-factor sign-in was turned off',
        'Your account no longer asks for an authenticator code. If you didn''t do this, secure your account now.',
        'critical', array['secure_account'], '{}'::jsonb, true, '[]'::jsonb, 'mfa_off:' || old.id);
    end if;
  exception when others then
    raise warning 'notify_mfa_change: %', sqlerrm;
  end;
  return null;
end;
$$;

-- Triggers on Supabase's auth schema: skipped (with a notice) if this project
-- doesn't allow them — everything else keeps working.
do $$ begin
  drop trigger if exists auth_users_security_notify on auth.users;
  create trigger auth_users_security_notify after update of encrypted_password, email on auth.users
    for each row execute function public.notify_auth_change();
exception when insufficient_privilege then
  raise notice 'skipped the auth.users trigger (no permission): password/email alerts disabled';
end $$;
do $$ begin
  drop trigger if exists auth_mfa_notify on auth.mfa_factors;
  create trigger auth_mfa_notify after insert or update of status or delete on auth.mfa_factors
    for each row execute function public.notify_mfa_change();
exception when insufficient_privilege or undefined_table then
  raise notice 'skipped the auth.mfa_factors trigger: two-factor alerts disabled';
end $$;
do $$ begin
  grant execute on function public.notify_auth_change(), public.notify_mfa_change() to supabase_auth_admin;
exception when undefined_object then null; end $$;

-- ------------------------------------------------ platform / community --
create or replace function public.notify_marketplace_status()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.status = 'removed' and old.status <> 'removed' then
    perform public.notify(new.author_id, 'platform', 'marketplace_removed',
      '“' || new.name || '” was removed from the marketplace',
      'Venband moderators removed it. People who installed it keep their copy.', 'warning',
      array['view_guidelines', 'open_theme_studio'],
      jsonb_build_object('item', new.id, 'kind', new.kind, 'reason', new.removed_reason), true,
      jsonb_build_array(jsonb_build_object('name', 'Item', 'value', new.name),
                        jsonb_build_object('name', 'Reason', 'value', coalesce(new.removed_reason, '—'))), null);
  elsif old.status = 'removed' and new.status <> 'removed' then
    perform public.notify(new.author_id, 'platform', 'marketplace_restored',
      '“' || new.name || '” is back in the marketplace', 'Venband moderators restored it.', 'info',
      array['open_theme_studio'], jsonb_build_object('item', new.id), false, '[]'::jsonb, null);
  end if;
  return null;
end;
$$;
drop trigger if exists themes_status_notify on public.themes;
create trigger themes_status_notify after update of status on public.themes
  for each row execute function public.notify_marketplace_status();

create or replace function public.notify_report_handled()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.reporter_id is not null and old.status = 'under_review' and new.status in ('actioned', 'dismissed') then
    perform public.notify(new.reporter_id, 'community', 'report_' || new.status,
      case when new.status = 'actioned' then 'We acted on your report' else 'We reviewed your report' end,
      case when new.status = 'actioned'
           then 'Thanks — what you reported broke Venband’s guidelines, and our moderators took action.'
           else 'Thanks — our moderators reviewed it and didn’t find a rule violation this time.' end,
      'info', array['view_guidelines'], jsonb_build_object('report', new.id, 'kind', new.kind), false, '[]'::jsonb,
      'report:' || new.id || ':' || new.status);
  end if;
  return null;
end;
$$;
drop trigger if exists reports_status_notify on public.reports;
create trigger reports_status_notify after update of status on public.reports
  for each row execute function public.notify_report_handled();

-- --------------------------------------------- official identity guards --
-- The 'venband' preset is the moderation toolkit anyone may add to their server;
-- what makes a bot OFFICIAL is being owned by the system account. So the preset
-- stays open, but the names "Venband" / "Official" are reserved.
create or replace function public.guard_official_app()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.owner_id = '3fff0000-0000-4000-8000-0000000000bd' then return new; end if;
  if tg_op = 'INSERT' or new.name is distinct from old.name then
    if new.name ~* '(venband|official)' then raise exception 'names containing “Venband” or “Official” are reserved'; end if;
  end if;
  return new;
end;
$$;
drop trigger if exists applications_official_guard on public.applications;
create trigger applications_official_guard before insert or update on public.applications
  for each row execute function public.guard_official_app();

create or replace function public.guard_bot_display_name()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.username is not null and new.username ~* '(venband|official|moderator|staff|admin|system)'
     and not exists (select 1 from public.applications a
                      where a.id = new.app_id and a.owner_id = '3fff0000-0000-4000-8000-0000000000bd') then
    new.username := null; -- fall back to the bot's own (non-reserved) name
  end if;
  return new;
end;
$$;
drop trigger if exists bot_messages_name_guard on public.bot_messages;
create trigger bot_messages_name_guard before insert or update of username on public.bot_messages
  for each row execute function public.guard_bot_display_name();

-- ------------------------------------------------------------------ grants --
do $$
declare fn text;
begin
  foreach fn in array array[
    'public.official_dm(uuid, text, text, text, jsonb, text)',
    'public.notify(uuid, text, text, text, text, text, text[], jsonb, boolean, jsonb, text)',
    'public.notify_account_restored()', 'public.notify_new_signin()', 'public.notify_auth_change()',
    'public.notify_mfa_change()', 'public.notify_marketplace_status()', 'public.notify_report_handled()',
    'public.guard_official_app()', 'public.guard_bot_display_name()'
  ] loop
    execute format('revoke execute on function %s from public, anon, authenticated', fn);
  end loop;
end $$;
revoke execute on function public.mark_notifications_read(uuid[]) from public, anon;
grant execute on function public.mark_notifications_read(uuid[]) to authenticated;
revoke execute on function public.revoke_device(uuid) from public, anon;
grant execute on function public.revoke_device(uuid) to authenticated;

notify pgrst, 'reload schema';

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- 20261106020000_badge_catalog.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- Badges: display choices, categories, rarity, limited editions (20261106020000)
--
--   * profiles.badge_display: which of YOUR badges you show, in your order.
--     NULL = show all (default). Staff badges (founder, owner, admin, moderator,
--     staff) always show — people need to be able to recognise real staff — so
--     they're never stored here. Only set through set_badge_display(), which only
--     accepts badges you actually hold. Nobody can award themselves a badge:
--     `badges` itself is still changed only by staff (mod_set_badges).
--   * custom badges get a category, a rarity, an optional "awardable until" date
--     (limited editions) and can be retired (kept by holders, no new awards).
--   * awarding a badge sends the holder a notification; removing one also
--     removes it from their display list.
--
-- Safe to run more than once.
-- =============================================================================

alter table public.profiles add column if not exists badge_display text[];
do $$ begin
  alter table public.profiles add constraint profiles_badge_display_size check (badge_display is null or cardinality(badge_display) <= 20);
exception when duplicate_object then null; end $$;

alter table public.custom_badges
  add column if not exists category text not null default 'special',
  add column if not exists rarity text not null default 'rare',
  add column if not exists awardable_until timestamptz,
  add column if not exists retired boolean not null default false;
do $$ begin
  alter table public.custom_badges add constraint custom_badges_category_check
    check (category in ('staff', 'community', 'developer', 'creator', 'supporter', 'achievement', 'event', 'seasonal', 'special'));
exception when duplicate_object then null; end $$;
do $$ begin
  alter table public.custom_badges add constraint custom_badges_rarity_check
    check (rarity in ('common', 'uncommon', 'rare', 'epic', 'legendary'));
exception when duplicate_object then null; end $$;

create or replace function public.protected_badges()
returns text[] language sql immutable set search_path = '' as $$
  select array['founder', 'owner', 'admin', 'moderator', 'staff']::text[];
$$;

-- ---------------------------------------------------------- your display --
create or replace function public.set_badge_display(p_ids text[])
returns text[] language plpgsql security definer set search_path = '' as $$
declare
  v_have text[];
  v_out text[] := '{}';
  b text;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select badges into v_have from public.profiles where id = auth.uid();
  if p_ids is null then
    update public.profiles set badge_display = null where id = auth.uid();
    return null;
  end if;
  if cardinality(p_ids) > 20 then raise exception 'you can show up to 20 badges'; end if;
  foreach b in array p_ids loop
    if b = any (public.protected_badges()) then continue; end if; -- always shown anyway
    if not (b = any (coalesce(v_have, '{}'))) then raise exception 'you don''t have the % badge', b; end if;
    if not (b = any (v_out)) then v_out := v_out || b; end if;
  end loop;
  update public.profiles set badge_display = v_out where id = auth.uid();
  return v_out;
end;
$$;

-- --------------------------------------------- awards, limits, notifications --
create or replace function public.guard_badge_changes()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  v_added text[];
  b text;
  c public.custom_badges%rowtype;
begin
  if new.badges is not distinct from old.badges then return new; end if;
  v_added := array(select x from unnest(coalesce(new.badges, '{}')) x where not (x = any (coalesce(old.badges, '{}'))));
  foreach b in array v_added loop
    select * into c from public.custom_badges where id = b;
    if found and (c.retired or (c.awardable_until is not null and c.awardable_until < now())) then
      raise exception 'the “%” badge can''t be awarded any more', c.name;
    end if;
  end loop;
  -- a removed badge also leaves the display list
  if new.badge_display is not null then
    new.badge_display := array(select x from unnest(new.badge_display) x where x = any (coalesce(new.badges, '{}')));
  end if;
  return new;
end;
$$;
drop trigger if exists profiles_badges_guard on public.profiles;
create trigger profiles_badges_guard before update of badges on public.profiles
  for each row execute function public.guard_badge_changes();

create or replace function public.notify_badge_awarded()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  b text;
  v_name text;
begin
  foreach b in array array(select x from unnest(coalesce(new.badges, '{}')) x where not (x = any (coalesce(old.badges, '{}')))) loop
    select name into v_name from public.custom_badges where id = b;
    v_name := coalesce(v_name, initcap(replace(b, '_', ' ')));
    perform public.notify(new.id, 'platform', 'badge_awarded', 'You got the ' || v_name || ' badge',
      'It now shows on your profile. Choose which badges you show in Settings → Profile.', 'info', '{}',
      jsonb_build_object('badge', b), false, '[]'::jsonb, 'badge:' || b);
  end loop;
  return null;
end;
$$;
drop trigger if exists profiles_badges_notify on public.profiles;
create trigger profiles_badges_notify after update of badges on public.profiles
  for each row execute function public.notify_badge_awarded();

-- ------------------------------------------------- the badge designer --
drop function if exists public.save_custom_badge(text, text, text, text);
create or replace function public.save_custom_badge(
  p_id text, p_name text, p_description text, p_image_url text,
  p_category text default 'special', p_rarity text default 'rare',
  p_awardable_until timestamptz default null, p_retired boolean default false)
returns text language plpgsql security definer set search_path = '' as $$
declare
  v_id text := 'c_' || regexp_replace(lower(btrim(coalesce(p_id, ''))), '^c_', '');
begin
  if not public.can_design_badges() then raise exception 'only Venband owners and founders can make badges'; end if;
  if p_image_url !~ '/storage/v1/object/public/badges/' then raise exception 'upload the badge picture first'; end if;
  insert into public.custom_badges (id, name, description, image_url, created_by, category, rarity, awardable_until, retired)
  values (v_id, btrim(p_name), btrim(coalesce(p_description, '')), p_image_url, auth.uid(),
          coalesce(p_category, 'special'), coalesce(p_rarity, 'rare'), p_awardable_until, coalesce(p_retired, false))
  on conflict (id) do update
    set name = excluded.name, description = excluded.description, image_url = excluded.image_url,
        category = excluded.category, rarity = excluded.rarity, awardable_until = excluded.awardable_until,
        retired = excluded.retired;
  insert into public.mod_actions (actor_id, action, detail) values (auth.uid(), 'badge_design', v_id);
  return v_id;
end;
$$;

-- ------------------------------------------------------------------ grants --
revoke execute on function public.set_badge_display(text[]) from public, anon;
grant execute on function public.set_badge_display(text[]) to authenticated;
revoke execute on function public.save_custom_badge(text, text, text, text, text, text, timestamptz, boolean) from public, anon;
grant execute on function public.save_custom_badge(text, text, text, text, text, text, timestamptz, boolean) to authenticated;
revoke execute on function public.guard_badge_changes() from public, anon, authenticated;
revoke execute on function public.notify_badge_awarded() from public, anon, authenticated;

notify pgrst, 'reload schema';

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- 20261106030000_fix_dm_blocked.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- Fix: owners / admins / founders couldn't send any DM (20261106030000)
--
-- dm_blocked() is meant to say "this DM is read-only because one side blocked
-- the other — except for people with force-contact powers". It was written as
-- `can_force_contact(p_user) OR blocked`, so for exactly those people it was
-- ALWAYS true, and messages_insert (`not dm_blocked(channel_id)`) refused every
-- DM they sent — including to friends ("one of you has blocked the other").
--
-- That bug also hid a second one, fixed here too: channel_perm_for_user() gave a
-- server's owner every permission even while the server was in review, closed or
-- banned, so the owner could keep posting in a frozen server.
--
-- Safe to run more than once.
-- =============================================================================

create or replace function public.dm_blocked(p_channel uuid, p_user uuid default auth.uid())
returns boolean language sql stable security definer set search_path = '' as $$
  select not public.can_force_contact(p_user)
     and exists (
       select 1 from public.channels c
       join public.dm_participants o on o.channel_id = c.id and o.user_id <> p_user
       where c.id = p_channel and c.type = 'dm' and not c.is_group
         and public.is_blocked_between(o.user_id, p_user));
$$;

create or replace function public.channel_perm_for_user(p_channel uuid, p_user uuid default auth.uid())
returns bigint language plpgsql stable security definer set search_path = '' as $$
declare
  c record;
  v_base bigint;
  v_out bigint;
  v_row record;
begin
  select id, server_id, type, category into c from public.channels where id = p_channel;
  if not found then return 0; end if;

  -- DMs are wide open for their participants.
  if c.type = 'dm' then
    if exists (select 1 from public.dm_participants where channel_id = p_channel and user_id = p_user)
      then return 2147483647; end if;
    return 0;
  end if;

  if not public.is_server_member(c.server_id, p_user) then return 0; end if;
  -- a server in review / closed / banned is frozen for everyone, its owner included
  -- (server_permissions already returns 0 then; the owner shortcut below skipped it)
  if (select status from public.servers where id = c.server_id) is distinct from 'active' then return 0; end if;
  if (select owner_id from public.servers where id = c.server_id) = p_user then return 2147483647; end if;

  v_base := public.server_permissions(c.server_id, p_user);
  if (v_base & 1) = 1 then return 2147483647; end if;
  v_out := v_base;

  -- Overwrites never grant or strip server-wide powers (Administrator, Manage Server).
  -- Category-level overwrites.
  for v_row in
    select o.target_type, o.target_id, o.allow, o.deny,
           case when o.target_type = 'member' then 2147483647 else coalesce(r.position, 0) end as pos
      from public.channel_overwrites o
      left join public.roles r on r.id = o.target_id and o.target_type = 'role'
     where o.server_id = c.server_id and o.category = c.category
     order by pos, o.target_id
  loop
    if v_row.target_type = 'role' and not exists (select 1 from public.member_roles mr
                                                  where mr.role_id = v_row.target_id
                                                    and mr.user_id = p_user
                                                    and mr.server_id = c.server_id) then
      continue;
    end if;
    if v_row.target_type = 'member' and v_row.target_id <> p_user then continue; end if;
    v_out := (v_out & ~(v_row.deny & ~3)) | (v_row.allow & ~3);
  end loop;

  -- Channel-level overwrites.
  for v_row in
    select o.target_type, o.target_id, o.allow, o.deny,
           case when o.target_type = 'member' then 2147483647 else coalesce(r.position, 0) end as pos
      from public.channel_overwrites o
      left join public.roles r on r.id = o.target_id and o.target_type = 'role'
     where o.channel_id = c.id
     order by pos, o.target_id
  loop
    if v_row.target_type = 'role' and not exists (select 1 from public.member_roles mr
                                                  where mr.role_id = v_row.target_id
                                                    and mr.user_id = p_user
                                                    and mr.server_id = c.server_id) then
      continue;
    end if;
    if v_row.target_type = 'member' and v_row.target_id <> p_user then continue; end if;
    v_out := (v_out & ~(v_row.deny & ~3)) | (v_row.allow & ~3);
  end loop;

  return v_out;
end;
$$;

notify pgrst, 'reload schema';

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- 20261106040000_cosmetics_badges.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- Cosmetics + badges (20261106040000)
--
--   * new nameplates (starfield, koi, fireflies, snowfall, synthwave, storm) and
--     avatar frames (galaxy, lightning, crystal)
--   * profile effects: profiles.profile_effect — particles over your profile card
--   * new badges: developer (Venband dev team, always shown), verified (user),
--     verified_bot, verified_server, contributor, beta_tester. Developer and the
--     verified badges can only be handed out by admins, like staff badges.
--
-- Safe to run more than once.
-- =============================================================================

alter table public.profiles drop constraint if exists profiles_nameplate_check;
alter table public.profiles add constraint profiles_nameplate_check
  check (nameplate in ('none', 'aurora', 'ember', 'ocean', 'sakura', 'circuit', 'noir', 'gold', 'custom',
                       'starfield', 'koi', 'fireflies', 'snowfall', 'synthwave', 'storm'));

alter table public.profiles drop constraint if exists profiles_avatar_frame_check;
alter table public.profiles add constraint profiles_avatar_frame_check
  check (avatar_frame in ('none', 'neon', 'flame', 'frost', 'rainbow', 'gold', 'sakura', 'pixel', 'orbit', 'hearts', 'glitch',
                          'galaxy', 'lightning', 'crystal'));

alter table public.profiles add column if not exists profile_effect text not null default 'none';
alter table public.profiles drop constraint if exists profiles_profile_effect_check;
alter table public.profiles add constraint profiles_profile_effect_check
  check (profile_effect in ('none', 'sparkles', 'hearts', 'sakura', 'snow', 'embers', 'leaves', 'bubbles', 'confetti',
                            'shooting_stars', 'fireflies', 'aurora'));
grant update (profile_effect) on public.profiles to authenticated;

-- ------------------------------------------------------------------ badges --
create or replace function public.all_badges()
returns text[] language sql stable security definer set search_path = '' as $$
  select array['founder', 'owner', 'admin', 'moderator', 'staff', 'developer', 'partner', 'verified', 'verified_bot',
               'verified_server', 'verified_dev', 'bug_hunter', 'bug_hunter_gold', 'og', 'early_supporter', 'supporter',
               'translator', 'contributor', 'beta_tester', 'event_winner']::text[]
         || coalesce((select array_agg(id order by created_at) from public.custom_badges), '{}');
$$;

-- staff badges always show (the holder can't hide them)
create or replace function public.protected_badges()
returns text[] language sql immutable set search_path = '' as $$
  select array['founder', 'owner', 'admin', 'moderator', 'staff', 'developer']::text[];
$$;

create or replace function public.mod_set_badges(p_user uuid, p_badges text[])
returns void language plpgsql security definer set search_path = '' as $$
declare
  v_new text[];
  v_old text[];
  v_staff_badges text[] := array['owner', 'admin', 'moderator', 'staff', 'developer', 'verified', 'verified_bot', 'verified_server'];
begin
  if not public.mod_can_target(p_user) then raise exception 'you can''t change this account'; end if;
  select coalesce(array_agg(distinct b order by b), '{}') into v_new
  from unnest(coalesce(p_badges, '{}')) b where b = any (public.all_badges());
  select badges into v_old from public.profiles where id = p_user;
  if not public.is_top_staff() then
    if public.platform_rank() < 2 and (
         (select coalesce(array_agg(b), '{}') from unnest(v_new) b where b = any (v_staff_badges))
         is distinct from
         (select coalesce(array_agg(b order by b), '{}') from unnest(v_old) b where b = any (v_staff_badges))) then
      raise exception 'only admins can change staff and verification badges';
    end if;
    if public.platform_rank() < 3 and (('owner' = any (v_new)) <> ('owner' = any (v_old))) then
      raise exception 'only the owner can change the owner badge';
    end if;
  end if;
  update public.profiles set badges = v_new where id = p_user;
  insert into public.mod_actions (actor_id, target_user, action, detail)
  values (auth.uid(), p_user, 'badges', array_to_string(v_new, ', '));
end;
$$;

notify pgrst, 'reload schema';

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- 20261106050000_staff_permissions_appeals.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- Staff permissions, appeals, audit search, theme / bot moderation (20261106050000)
--
--   * Granular staff permissions. profiles.staff_permissions (NULL = the role's
--     defaults, which are exactly what each rank could do before, so nothing
--     changes until an owner narrows someone down). Owners / founders always
--     have every permission. Checked by staff_can() inside every moderation
--     function — the app hiding a button is never the protection.
--       accounts  limit / very-limit / restore accounts      (moderator+)
--       ban       ban and unban accounts                     (moderator+)
--       badges    award badges                               (moderator+)
--       servers   review / verify / close / ban servers      (moderator+)
--       marketplace  remove / restore themes & styles        (moderator+)
--       apps      disable / enable bots and apps             (moderator+)
--       audit     read the staff audit log                   (moderator+)
--       reports   the Report Centre                          (admin+)
--       appeals   decide appeals                             (admin+)
--   * Appeals: people can appeal an account restriction, a removed marketplace
--     item or a disabled bot, once at a time; staff accept (undoes it) or deny
--     with a reply; the person is notified either way.
--   * Reports for marketplace items and bots (report_item), shown in the
--     Report Centre next to message / user reports.
--   * mod_log_search: audit log search and filters.
--
-- Safe to run more than once.
-- =============================================================================

-- ------------------------------------------------------- staff permissions --
create or replace function public.staff_permission_keys()
returns text[] language sql immutable set search_path = '' as $$
  select array['accounts', 'ban', 'badges', 'servers', 'marketplace', 'apps', 'audit', 'reports', 'appeals']::text[];
$$;

alter table public.profiles add column if not exists staff_permissions text[];
do $$ begin
  alter table public.profiles add constraint profiles_staff_permissions_valid
    check (staff_permissions is null or staff_permissions <@ array['accounts', 'ban', 'badges', 'servers', 'marketplace', 'apps', 'audit', 'reports', 'appeals']::text[]);
exception when duplicate_object then null; end $$;

create or replace function public.staff_permissions_for(p_user uuid default auth.uid())
returns text[] language sql stable security definer set search_path = '' as $$
  select case
    when public.is_top_staff(p_user) then public.staff_permission_keys()
    when public.platform_rank(p_user) < 1 then '{}'::text[]
    else coalesce((select staff_permissions from public.profiles where id = p_user),
                  case when public.platform_rank(p_user) >= 2 then public.staff_permission_keys()
                       else array['accounts', 'ban', 'badges', 'servers', 'marketplace', 'apps', 'audit']::text[] end)
  end;
$$;

create or replace function public.staff_can(p_perm text, p_user uuid default auth.uid())
returns boolean language sql stable security definer set search_path = '' as $$
  select p_perm = any (public.staff_permissions_for(p_user));
$$;

create or replace function public.my_staff_permissions()
returns text[] language sql stable security definer set search_path = '' as $$
  select public.staff_permissions_for(auth.uid());
$$;

-- Owners / founders set what a staff member may do. NULL = back to the role's defaults.
create or replace function public.mod_set_staff_permissions(p_user uuid, p_perms text[])
returns text[] language plpgsql security definer set search_path = '' as $$
declare
  v_clean text[];
begin
  if not public.is_top_staff() then raise exception 'only Venband owners can change staff permissions'; end if;
  if p_user = auth.uid() then raise exception 'you can''t change your own permissions'; end if;
  if public.platform_rank(p_user) < 1 then raise exception 'they aren''t Venband staff'; end if;
  if public.is_top_staff(p_user) then raise exception 'owners always have every permission'; end if;
  if p_perms is not null then
    if not (p_perms <@ public.staff_permission_keys()) then raise exception 'unknown permission'; end if;
    select coalesce(array_agg(distinct x order by x), '{}') into v_clean from unnest(p_perms) x;
  end if;
  update public.profiles set staff_permissions = v_clean where id = p_user;
  insert into public.mod_actions (actor_id, target_user, action, detail)
  values (auth.uid(), p_user, 'staff_permissions', coalesce(array_to_string(v_clean, ', '), 'role defaults'));
  return public.staff_permissions_for(p_user);
end;
$$;

-- ----------------------------------------- existing tools, now permission-checked --
create or replace function public.mod_set_account_status(p_user uuid, p_status text, p_reason text default '', p_server uuid default null)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if p_status not in ('active', 'limited', 'very_limited', 'banned') then raise exception 'unknown status'; end if;
  if p_user = auth.uid() or not public.mod_can_target(p_user) then raise exception 'you can''t change this account'; end if;
  -- banning / unbanning needs the "ban" permission, other restrictions "accounts"
  if not public.staff_can(case when p_status = 'banned' or (select account_status from public.profiles where id = p_user) = 'banned'
                               then 'ban' else 'accounts' end) then
    raise exception 'your staff permissions don''t include this';
  end if;
  update public.profiles set account_status = p_status where id = p_user;
  -- banned accounts are signed out everywhere and can't sign in again
  update auth.users set banned_until = case when p_status = 'banned' then 'infinity'::timestamptz end
  where id = p_user;
  if p_status = 'banned' then delete from auth.sessions where user_id = p_user; end if;
  insert into public.mod_actions (actor_id, target_user, action, detail, reason)
  values (auth.uid(), p_user, 'account_status', p_status, left(coalesce(p_reason, ''), 1000));
  if p_status in ('limited', 'very_limited', 'banned') then
    perform public.venband_notice(p_user, p_status, p_reason, p_server);
  end if;
end;
$$;

create or replace function public.mod_set_badges(p_user uuid, p_badges text[])
returns void language plpgsql security definer set search_path = '' as $$
declare
  v_new text[];
  v_old text[];
  v_staff_badges text[] := array['owner', 'admin', 'moderator', 'staff', 'developer', 'verified', 'verified_bot', 'verified_server'];
begin
  if not public.mod_can_target(p_user) then raise exception 'you can''t change this account'; end if;
  if not public.staff_can('badges') then raise exception 'your staff permissions don''t include badges'; end if;
  select coalesce(array_agg(distinct b order by b), '{}') into v_new
  from unnest(coalesce(p_badges, '{}')) b where b = any (public.all_badges());
  select badges into v_old from public.profiles where id = p_user;
  if not public.is_top_staff() then
    if public.platform_rank() < 2 and (
         (select coalesce(array_agg(b), '{}') from unnest(v_new) b where b = any (v_staff_badges))
         is distinct from
         (select coalesce(array_agg(b order by b), '{}') from unnest(v_old) b where b = any (v_staff_badges))) then
      raise exception 'only admins can change staff and verification badges';
    end if;
    if public.platform_rank() < 3 and (('owner' = any (v_new)) <> ('owner' = any (v_old))) then
      raise exception 'only the owner can change the owner badge';
    end if;
  end if;
  update public.profiles set badges = v_new where id = p_user;
  insert into public.mod_actions (actor_id, target_user, action, detail)
  values (auth.uid(), p_user, 'badges', array_to_string(v_new, ', '));
end;
$$;

create or replace function public.mod_server_action(p_server uuid, p_action text, p_reason text default '')
returns void language plpgsql security definer set search_path = '' as $$
declare
  v_owner uuid;
begin
  if not public.is_staff() then raise exception 'staff only'; end if;
  if not public.staff_can('servers') then raise exception 'your staff permissions don''t include servers'; end if;
  select owner_id into v_owner from public.servers where id = p_server;
  if v_owner is null then raise exception 'server not found'; end if;
  perform set_config('venband.mod', 'on', true);
  case p_action
    when 'review'   then update public.servers set status = 'review' where id = p_server;
    when 'approve'  then update public.servers set status = 'active' where id = p_server;
    when 'reject'   then
      update public.servers set status = 'closed', verified = false where id = p_server;
      if public.platform_rank(v_owner) < public.platform_rank() then
        update public.profiles set account_status = 'very_limited'
        where id = v_owner and account_status in ('active', 'limited');
        if found then
          perform public.venband_notice(v_owner, 'very_limited', p_reason, p_server);
        end if;
      end if;
    when 'ban'      then update public.servers set status = 'banned', verified = false where id = p_server;
    when 'unban'    then update public.servers set status = 'active' where id = p_server;
    when 'verify'   then update public.servers set verified = true where id = p_server;
    when 'unverify' then update public.servers set verified = false where id = p_server;
    else raise exception 'unknown action';
  end case;
  perform set_config('venband.mod', 'off', true);
  insert into public.mod_actions (actor_id, target_server, target_user, action, reason)
  values (auth.uid(), p_server, v_owner, 'server_' || p_action, left(coalesce(p_reason, ''), 1000));
end;
$$;

create or replace function public.handle_report(p_report uuid, p_status text, p_note text default '')
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not public.staff_can('reports') then raise exception 'your staff permissions don''t include reports'; end if;
  if p_status not in ('under_review', 'actioned', 'dismissed') then raise exception 'unknown status'; end if;
  update public.reports
  set status = p_status, handled_by = auth.uid(), handled_note = left(coalesce(p_note, ''), 1000),
      handled_at = case when p_status = 'under_review' then null else now() end
  where id = p_report;
  insert into public.mod_actions (actor_id, target_user, action, detail, reason)
  select auth.uid(), r.target_user, 'report_' || p_status, r.kind, left(coalesce(p_note, ''), 1000)
  from public.reports r where r.id = p_report;
end;
$$;

create or replace function public.mod_log(p_limit integer default 50)
returns table (id uuid, actor text, target_user text, target_server text, action text, detail text,
               reason text, created_at timestamptz)
language sql stable security definer set search_path = '' as $$
  select m.id, a.username, u.username, s.name, m.action, m.detail, m.reason, m.created_at
  from public.mod_actions m
  left join public.profiles a on a.id = m.actor_id
  left join public.profiles u on u.id = m.target_user
  left join public.servers s on s.id = m.target_server
  where public.is_staff() and public.staff_can('audit')
  order by m.created_at desc
  limit least(coalesce(p_limit, 50), 200);
$$;

create or replace function public.theme_set_status(p_theme uuid, p_status text, p_reason text default '')
returns void language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  t public.themes%rowtype;
  v_staff boolean := public.is_staff() and public.staff_can('marketplace');
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  if p_status not in ('published', 'unpublished', 'removed') then raise exception 'unknown status'; end if;
  select * into t from public.themes where id = p_theme for update;
  if not found then raise exception 'not found'; end if;

  if p_status = 'removed' or t.status = 'removed' then
    if not v_staff then raise exception 'only Venband staff can remove or restore marketplace items'; end if;
    if p_status = 'removed' and char_length(btrim(coalesce(p_reason, ''))) < 3 then raise exception 'give a reason for removing it'; end if;
    if p_status <> 'removed' and t.version < 1 then raise exception 'it was never published'; end if;
    update public.themes
       set status = p_status, updated_at = now(),
           removed_reason = case when p_status = 'removed' then left(btrim(p_reason), 500) else null end
     where id = p_theme;
    insert into public.mod_actions (actor_id, target_user, action, detail, reason)
    values (v_uid, t.author_id, 'marketplace_' || case when p_status = 'removed' then 'remove' else 'restore' end,
            t.kind || ' “' || t.name || '” (' || t.id || ')', left(coalesce(p_reason, ''), 1000));
    return;
  end if;

  if t.author_id <> v_uid then raise exception 'only the creator can change this'; end if;
  if p_status = 'published' and t.version < 1 then raise exception 'publish it first'; end if;
  update public.themes set status = p_status, updated_at = now() where id = p_theme;
end;
$$;

-- ------------------------------------------------------------ audit search --
create or replace function public.mod_log_search(
  p_query text default '', p_action text default '', p_from timestamptz default null, p_to timestamptz default null,
  p_before timestamptz default null, p_limit integer default 100)
returns table (id uuid, actor text, actor_id uuid, target_user text, target_user_id uuid, target_server text,
               target_server_id uuid, action text, detail text, reason text, created_at timestamptz)
language sql stable security definer set search_path = '' as $$
  select m.id, a.username, m.actor_id, u.username, m.target_user, s.name, m.target_server, m.action, m.detail, m.reason, m.created_at
  from public.mod_actions m
  left join public.profiles a on a.id = m.actor_id
  left join public.profiles u on u.id = m.target_user
  left join public.servers s on s.id = m.target_server
  where public.is_staff() and public.staff_can('audit')
    and (coalesce(p_action, '') = '' or m.action like replace(replace(p_action, '%', ''), '_', '\_') || '%')
    and (p_from is null or m.created_at >= p_from)
    and (p_to is null or m.created_at < p_to)
    and (p_before is null or m.created_at < p_before)
    and (coalesce(btrim(p_query), '') = ''
         or a.username ilike '%' || btrim(p_query) || '%' or u.username ilike '%' || btrim(p_query) || '%'
         or s.name ilike '%' || btrim(p_query) || '%' or m.detail ilike '%' || btrim(p_query) || '%'
         or m.reason ilike '%' || btrim(p_query) || '%' or m.target_user::text = btrim(p_query)
         or m.target_server::text = btrim(p_query) or m.actor_id::text = btrim(p_query))
  order by m.created_at desc
  limit least(greatest(coalesce(p_limit, 100), 1), 200);
$$;

-- ------------------------------------------------- bots: disable / enable --
create or replace function public.mod_app_action(p_app uuid, p_action text, p_reason text default '')
returns void language plpgsql security definer set search_path = '' as $$
declare
  a public.applications%rowtype;
begin
  if not public.staff_can('apps') then raise exception 'your staff permissions don''t include bots and apps'; end if;
  if p_action not in ('disable', 'enable') then raise exception 'unknown action'; end if;
  select * into a from public.applications where id = p_app;
  if not found then raise exception 'not found'; end if;
  if a.owner_id = '3fff0000-0000-4000-8000-0000000000bd' and not public.is_top_staff() then
    raise exception 'only owners can change Venband''s own apps';
  end if;
  if p_action = 'disable' and char_length(btrim(coalesce(p_reason, ''))) < 3 then raise exception 'give a reason'; end if;
  perform set_config('venband.mod', 'on', true);
  update public.applications set status = case when p_action = 'disable' then 'disabled' else 'active' end where id = p_app;
  perform set_config('venband.mod', 'off', true);
  insert into public.mod_actions (actor_id, target_user, action, detail, reason)
  values (auth.uid(), a.owner_id, 'app_' || p_action, a.name || ' (' || a.id || ')', left(coalesce(p_reason, ''), 1000));
  perform public.notify(a.owner_id, 'platform', 'app_' || p_action,
    case when p_action = 'disable' then 'Your bot “' || a.name || '” was disabled' else 'Your bot “' || a.name || '” is active again' end,
    case when p_action = 'disable' then 'Venband staff disabled it: ' || left(btrim(p_reason), 400) || E'\nYou can appeal in Settings → Security → Appeals.'
         else 'Venband staff lifted the restriction. It can post again.' end,
    case when p_action = 'disable' then 'warning' else 'info' end,
    case when p_action = 'disable' then array['open_appeals'] else '{}'::text[] end,
    jsonb_build_object('app', a.id));
end;
$$;

-- --------------------------------------------- reports for themes and bots --
alter table public.reports add column if not exists target_ref uuid;
alter table public.reports drop constraint if exists reports_kind_check;
alter table public.reports add constraint reports_kind_check check (kind in ('message', 'user', 'theme', 'app'));

-- message / user reports are inserted directly (they carry evidence decrypted on
-- the reporter's device); theme / bot reports only through report_item()
drop policy if exists reports_insert on public.reports;
create policy reports_insert on public.reports for insert to authenticated
  with check (
    reporter_id = auth.uid() and status = 'under_review' and handled_by is null
    and kind in ('message', 'user')
    and target_user is distinct from auth.uid()
    and (select count(*) from public.reports r where r.reporter_id = auth.uid() and r.created_at > now() - interval '1 hour') < 20
  );
drop policy if exists reports_select on public.reports;
create policy reports_select on public.reports for select to authenticated
  using (reporter_id = auth.uid() or public.staff_can('reports'));

create or replace function public.report_item(p_kind text, p_ref uuid, p_reason text)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  v_owner uuid;
  v_name text;
  v_id uuid;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  if char_length(btrim(coalesce(p_reason, ''))) not between 3 and 1000 then raise exception 'say what''s wrong (3–1000 characters)'; end if;
  if p_kind = 'theme' then
    select author_id, name into v_owner, v_name from public.themes where id = p_ref and status = 'published';
  elsif p_kind = 'app' then
    select owner_id, name into v_owner, v_name from public.applications where id = p_ref;
  else
    raise exception 'unknown kind';
  end if;
  if v_owner is null then raise exception 'not found'; end if;
  if v_owner = v_uid then raise exception 'you can''t report your own'; end if;
  if (select count(*) from public.reports r where r.reporter_id = v_uid and r.created_at > now() - interval '1 hour') >= 20 then
    raise exception 'too many reports — try again later';
  end if;
  if exists (select 1 from public.reports where reporter_id = v_uid and kind = p_kind and target_ref = p_ref and status = 'under_review') then
    raise exception 'you already reported this — staff will look at it';
  end if;
  insert into public.reports (reporter_id, kind, target_user, target_ref, reason, evidence)
  values (v_uid, p_kind, v_owner, p_ref, btrim(p_reason),
          jsonb_build_array(jsonb_build_object('id', p_ref, 'author_id', v_owner, 'author', coalesce(v_name, ''), 'text', coalesce(v_name, ''), 'at', now())))
  returning id into v_id;
  return v_id;
end;
$$;

-- ----------------------------------------------------------------- appeals --
create table if not exists public.appeals (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references public.profiles (id) on delete cascade,
  kind        text not null check (kind in ('account', 'theme', 'app')),
  target_ref  uuid,
  subject     text not null default '' check (char_length(subject) <= 200),
  message     text not null check (char_length(btrim(message)) between 10 and 2000),
  status      text not null default 'open' check (status in ('open', 'accepted', 'denied')),
  handled_by  uuid references public.profiles (id) on delete set null,
  response    text not null default '' check (char_length(response) <= 1000),
  created_at  timestamptz not null default now(),
  handled_at  timestamptz
);
create unique index if not exists appeals_one_open on public.appeals (user_id, kind, coalesce(target_ref, '00000000-0000-0000-0000-000000000000'::uuid)) where status = 'open';
create index if not exists appeals_status_idx on public.appeals (status, created_at);
alter table public.appeals enable row level security;
drop policy if exists appeals_select on public.appeals;
create policy appeals_select on public.appeals for select to authenticated
  using (user_id = auth.uid() or public.staff_can('appeals'));
revoke insert, update, delete on public.appeals from authenticated, anon;
grant select on public.appeals to authenticated;

create or replace function public.submit_appeal(p_kind text, p_ref uuid, p_message text)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  v_subject text;
  v_id uuid;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  if char_length(btrim(coalesce(p_message, ''))) not between 10 and 2000 then raise exception 'explain in 10–2000 characters'; end if;
  if p_kind = 'account' then
    select account_status into v_subject from public.profiles where id = v_uid;
    if v_subject is null or v_subject = 'active' then raise exception 'your account isn''t restricted'; end if;
    p_ref := null;
  elsif p_kind = 'theme' then
    select name into v_subject from public.themes where id = p_ref and author_id = v_uid and status = 'removed';
    if v_subject is null then raise exception 'that item wasn''t removed by staff'; end if;
  elsif p_kind = 'app' then
    select name into v_subject from public.applications where id = p_ref and owner_id = v_uid and status = 'disabled';
    if v_subject is null then raise exception 'that bot isn''t disabled'; end if;
  else
    raise exception 'unknown kind';
  end if;
  if exists (select 1 from public.appeals where user_id = v_uid and kind = p_kind and target_ref is not distinct from p_ref and status = 'open') then
    raise exception 'you already have an open appeal for this';
  end if;
  if exists (select 1 from public.appeals where user_id = v_uid and kind = p_kind and target_ref is not distinct from p_ref
             and status = 'denied' and handled_at > now() - interval '7 days') then
    raise exception 'this appeal was denied recently — you can appeal again 7 days after the decision';
  end if;
  if (select count(*) from public.appeals where user_id = v_uid and created_at > now() - interval '1 day') >= 5 then
    raise exception 'too many appeals today';
  end if;
  insert into public.appeals (user_id, kind, target_ref, subject, message)
  values (v_uid, p_kind, p_ref, left(v_subject, 200), btrim(p_message))
  returning id into v_id;
  return v_id;
end;
$$;

create or replace function public.handle_appeal(p_appeal uuid, p_accept boolean, p_response text default '')
returns void language plpgsql security definer set search_path = '' as $$
declare
  a public.appeals%rowtype;
begin
  if not public.staff_can('appeals') then raise exception 'your staff permissions don''t include appeals'; end if;
  select * into a from public.appeals where id = p_appeal for update;
  if not found then raise exception 'not found'; end if;
  if a.status <> 'open' then raise exception 'already decided'; end if;
  if a.user_id = auth.uid() then raise exception 'you can''t decide your own appeal'; end if;
  if not p_accept and char_length(btrim(coalesce(p_response, ''))) < 3 then raise exception 'tell them why it was denied'; end if;

  if p_accept then
    if a.kind = 'account' then
      if not public.mod_can_target(a.user_id) then raise exception 'you can''t change this account'; end if;
      update public.profiles set account_status = 'active' where id = a.user_id;
      update auth.users set banned_until = null where id = a.user_id;
    elsif a.kind = 'theme' then
      update public.themes set status = 'published', removed_reason = null, updated_at = now()
       where id = a.target_ref and status = 'removed' and version >= 1;
    elsif a.kind = 'app' then
      perform set_config('venband.mod', 'on', true);
      update public.applications set status = 'active' where id = a.target_ref;
      perform set_config('venband.mod', 'off', true);
    end if;
  end if;

  update public.appeals set status = case when p_accept then 'accepted' else 'denied' end,
         handled_by = auth.uid(), response = left(btrim(coalesce(p_response, '')), 1000), handled_at = now()
   where id = p_appeal;
  insert into public.mod_actions (actor_id, target_user, action, detail, reason)
  values (auth.uid(), a.user_id, 'appeal_' || case when p_accept then 'accepted' else 'denied' end,
          a.kind || ': ' || a.subject, left(coalesce(p_response, ''), 1000));
  perform public.notify(a.user_id, 'platform', 'appeal_result',
    case when p_accept then 'Your appeal was accepted' else 'Your appeal was denied' end,
    case when p_accept then 'Venband staff reviewed your appeal about ' || a.subject || ' and lifted it.'
         else 'Venband staff reviewed your appeal about ' || a.subject || '. Their reply: ' || left(btrim(p_response), 600) end,
    case when p_accept then 'info' else 'warning' end, array['open_appeals'], jsonb_build_object('appeal', a.id));
end;
$$;

